export const universitetichkitartibqonunlari = [
  {
    "id": 1,
    "descriptions_uz": "<h4>&nbsp;</h4>\r\n\r\n<h4>Urganch RANCH texnologiya universitetining ichki tartib QOIDALARI</h4>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Ichki tartib-qoidalari (ichki mehnat tartibi qoidalari)</strong><br />\r\n&nbsp;</p>\r\n\r\n<p>Mazkur Ichki tartib qoidalari (ichki mehnat tartibi qoidalari) (keyingi o&lsquo;rinlarda &ndash; Qoidalar) O&lsquo;zbekiston Respublikasining Mehnat kodeksi, &ldquo;Ta&rsquo;lim to&lsquo;g&lsquo;risida&rdquo;gi qonuni va boshqa oliy ta&rsquo;limga oid qonun va qonunosti hujjatlarni inobatga olgan holda ishlab chiqilgan hamda oliy ta&rsquo;lim muassasasi(keyingi o&lsquo;rinlarda &ndash; Universitet)dagi mehnat, o&lsquo;quv, ilmiy faoliyat va ta&rsquo;lim-tarbiya jarayoniga oid bo&lsquo;lgan munosabatlarni tartibga soluvchi lokal normativ hujjat hisoblanadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>1-bob.&nbsp;Umumiy qoidalar</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>1.1.&nbsp;Mazkur Qoidalarda quyidagi asosiy tushunchalardan foydalaniladi:</p>\r\n\r\n<p><strong>xodim</strong>&nbsp;&ndash; belgilangan yoshga etgan hamda Universitet bilan mehnat shartnomasini tuzgan O&lsquo;zbekiston Respublikasi fuqarolari, shuningdek, chet el fuqarolari va fuqaroligi bo&lsquo;lmagan shaxslar;</p>\r\n\r\n<p><strong>mehnat shartnomasi</strong>&nbsp;&ndash; xodim bilan Universitet o&lsquo;rtasida muayyan mutaxassislik, malaka, lavozim bo&lsquo;yicha ishni ichki mehnat tartibiga bo&lsquo;ysungan holda taraflar kelishuvi, shuningdek, mehnat to&lsquo;g&lsquo;risidagi qonunlar va boshqa normativ hujjatlar bilan belgilangan shartlar asosida haq evaziga bajarish haqidagi kelishuv;</p>\r\n\r\n<p><strong>professor-o&lsquo;qituvchilar</strong>&nbsp;&ndash; kafedra mudiri, professor, dotsent, katta o&lsquo;qituvchi, o&lsquo;qituvchi,&nbsp;o&lsquo;qituvchi-stajyor&nbsp;lavozimlariga ishga qabul qilingan xodimlar;</p>\r\n\r\n<p><strong>doktorant</strong>&nbsp;&ndash; Universitetga tayanch doktorantura yoki doktoranturaga belgilangan tartibda qabul qilingan shaxs;</p>\r\n\r\n<p><strong>mustaqil izlanuvchi</strong>&nbsp;&ndash; Universitetga mustaqil izlanuvchilikka belgilangan tartibda qabul qilingan shaxs;</p>\r\n\r\n<p><strong>talaba</strong>&nbsp;&ndash; bakalavriyat va magistratura&nbsp;darajalari bo&lsquo;yicha&nbsp;Universitetda mavjud ta&rsquo;lim yo&lsquo;nalishlari hamda&nbsp;mutaxassisliklar bo&lsquo;yicha ta&rsquo;lim olish uchun belgilangan tartibda qabul qilingan&nbsp;va ilm-fan, tarbiyani qabul qiluvchi shaxs.</p>\r\n\r\n<p>1.2.&nbsp;Ushbu Qoidalar Universitetning ichki mehnat tartibi, Universitet, rahbariyat, xodim, talaba, doktorant, mustaqil izlanuvchilarning burchlari, shuningdek, ishga qabul qilish, mehnat shartnomasini o&lsquo;zgartirish va mehnat shartnomasini bekor qilish, ta&rsquo;lim va tarbiya jarayonini tashkil etish tartibi, mehnat va o&lsquo;quv intizomi, ish vaqti, dam olish vaqti va undan foydalanish, shu bilan birga ish va o&lsquo;qishdagi yutuqlar uchun rag&lsquo;batlantirish, mehnat va o&lsquo;quv intizomini buzganlik uchun javobgarlik, Universitet hududi va binolar ichidagi tartib hamda ish beruvchi bilan xodim, doktorant, mustaqil izlanuvchi va talabalar o&lsquo;rtasida yuzaga keladigan boshqa huquqiy munosabatlarga oid masalalarni tartibga soladigan asosiy ichki normativ hujjat hisoblanadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>2-bob.&nbsp;Mehnat shartnomasini tuzish, o&lsquo;zgartirish va bekor qilish</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>2.1.&nbsp;Mehnat shartnomasini tuzish</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>2.1.1.&nbsp;Xodim bilan Universitet o&lsquo;rtasidagi mehnat munosabatla</p>\r\n\r\n<p>2.1.2.&nbsp;Ishga qabul qilish vaqtida ishga kirayotgan shaxs quyidagi hujjatlar:</p>\r\n\r\n<p>doimiy yashash yoki vaqtincha ro&lsquo;yxatdan o&lsquo;tgan manzili ko&lsquo;rsatilgan pasport yoki uning o&lsquo;rnini bosadigan boshqa hujjat;</p>\r\n\r\n<p>mehnat daftarchasi (birinchi marotaba ishga kirayotgan shaxslar bundan mustasno);</p>\r\n\r\n<p>harbiy xizmatga majburlar yoki chaqiriluvchilarga tegishli harbiy bilet yoki harbiy hisobda turganlik haqidagi guvohnoma;</p>\r\n\r\n<p>qonun hujjatlariga muvofiq bajarilishiga faqat maxsus tayyorgarlikka ega bo&lsquo;lgan shaxslargina qo&lsquo;yilishi mumkin bo&lsquo;lgan ishga kirish vaqtida ishga kiruvchining oliy yoki o&lsquo;rta maxsus, kasb-hunar o&lsquo;quv yurtini bitirganlik to&lsquo;g&lsquo;risidagi diplomi, mazkur ishni bajarish huquqini beruvchi guvohnoma (chet davlatlar hududida olingan diplom O&lsquo;zbekiston Respublikasi qonun hujjatlari bilan belgilangan tegishli tartibda nostrifikatsiyalangan (ekvivalentligi qayd etilgan)ligi haqida tegishli guvohnomasi);</p>\r\n\r\n<p>o&lsquo;rindoshlik asosida ishga kirayotgan shaxslar mehnat daftarchasi o&lsquo;rniga asosiy ish joyidan olgan ma&rsquo;lumotnomani taqdim etadi.</p>\r\n\r\n<p>Ishga qabul qilish vaqtida ishga kirayotgan shaxsdan qonun hujjatlarida ko&lsquo;rsatilmagan hujjatlarni talab qilish taqiqlanadi.</p>\r\n\r\n<p>Ishga kirayotgan shaxsning pasporti yoki shaxsini tasdiqlovchi boshqa hujjati haqiqiy bo&lsquo;lmasa, uni ishga qabul qilish rad etilishi mumkin.</p>\r\n\r\n<p>Kadrlar hisobini yuritish va ular haqida ma&rsquo;lumotlar bazasini shakllantirish maqsadida ishga qabul qilingan xodim tomonidan Kadrlar bo&lsquo;limiga quyidagi hujjatlar topshiriladi:</p>\r\n\r\n<p>so&lsquo;rovnoma;</p>\r\n\r\n<p>tarjimai hol;</p>\r\n\r\n<p>ma&rsquo;lumotnoma (ob&rsquo;ektivka);</p>\r\n\r\n<p>4 ta fotosurat (elektron varianti ham)</p>\r\n\r\n<p>2.1.3.&nbsp;After checking the completeness of the documents specified in the second to sixth headings of paragraph 4 of these Rules, the person applying for employment writes an application, which is registered at the University&#39;s registry office. The application must include the applicant&#39;s full name (first name, last name, and patronymic) without any abbreviations, and the position being applied for must correspond to the position specified in the staff schedule.</p>\r\n\r\n<p>2.1.4.&nbsp;Ishga qabul qilinayotgan xodim bilan ish beruvchi o&lsquo;rtasida quyidagilar haqida mehnat shartnomasi tuziladi:</p>\r\n\r\n<p>xodim ishga qabul qilinayotgan lavozim va ish joyi;</p>\r\n\r\n<p>mehnat shartnomasi muddati;</p>\r\n\r\n<p>ishning boshlanish kuni;</p>\r\n\r\n<p>taraflarning mehnat huquqlari va majburiyatlari;</p>\r\n\r\n<p>ish vaqti hamda mehnat ta&rsquo;tili berish tartibi;</p>\r\n\r\n<p>mehnatga haq to&lsquo;lash tartibi;</p>\r\n\r\n<p>mehnat qonunchiligida nazarda tutilgan boshqa holatlar.</p>\r\n\r\n<p>Mehnat shartnomasida uning amal qilish muddati ko&lsquo;rsatilmagan hollarda ushbu shartnoma nomuayyan muddatga tuzilgan hisoblanadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Muddatli mehnat shartnomasini tuzish mehnat to&lsquo;g&lsquo;risidagi qonunlar va boshqa normativ hujjatlarga muvofiq amalga oshiriladi.</p>\r\n\r\n<p>2.1.5.&nbsp;Ishga qabul qilinayotgan har bir xodim (shu jumladan, o&lsquo;rindoshlik asosida kiruvchilar) bilan mehnat shartnomasi bir xil yuridik kuchga ega bo&lsquo;lgan kamida ikki nusxada yozma shaklda tuziladi va ular tomonlarning har biriga saqlash uchun topshiriladi.</p>\r\n\r\n<p>Xodimning talabiga ko&lsquo;ra mehnat shartnomasi (kontrakt) u biladigan tilda tuziladi va davlat tilida tuzilgan shartnoma (kontrakt) bilan bir xil yuridik kuchga ega bo&lsquo;ladi.</p>\r\n\r\n<p>Mehnat shartnomasida taraflarning manzillari ko&lsquo;rsatiladi.</p>\r\n\r\n<p>Mehnat shartnomasi xodim va Universitet rektorining imzosi bilan tasdiqlanadi. Universitet rektorining imzosi Universitet gerbli muhri bilan tasdiqlanadi.</p>\r\n\r\n<p>2.1.6.&nbsp;Universitetning Kadrlar bo&lsquo;limi tomonidan O&lsquo;zbekiston Respublikasi Vazirlar Mahkamasining 2019 yil 5 dekabrdagi 971-son qarori bilan tasdiqlangan &ldquo;Yagona milliy mehnat tizimi&rdquo; idoralararo dasturiy-apparat kompleksida mehnat shartnomalarini ro&lsquo;yxatdan o&lsquo;tkazish, elektron mehnat daftarchalarini shakllantirish va yuritish tartibi to&lsquo;g&lsquo;risidagi nizomiga muvofiq xodim va ish beruvchi o&lsquo;rtasidagi mehnat munosabatlari (mehnat shartnomalarini tuzish, o&lsquo;zgartirish va bekor qilish, mehnat daftarchasini shakllantirish hamda yuritish va boshqalar) &ldquo;YAgona milliy mehnat tizimi&rdquo; idoralararo dasturiy-apparat kompleksida ro&lsquo;yxatga olinadi.</p>\r\n\r\n<p>2.1.7.&nbsp;Qonun hujjatlariga muvofiq tuzilgan mehnat shartnomasi tomonlar imzolagan kundan boshlab qonuniy kuchga kiradi. Xodim mehnat shartnomasida ko&lsquo;rsatilgan kundan boshlab mehnat vazifalarini bajarishga kirishadi. Agar mehnat shartnomasida ishning boshlanish kuni haqida shartlashilmagan bo&lsquo;lsa, xodim mehnat shartnomasi imzolangan ish kuni (smena)ning ertasidan kechikmay ishga tushishi lozim.</p>\r\n\r\n<p>2.1.8.&nbsp;Ish beruvchining ruxsati bilan ishga qabul qilishni tegishlicha rasmiylashtirmasdan turib ishga qo&lsquo;yilgan shaxs ishga tushgan birinchi kunidan boshlab mehnat shartnomasi tuzilgan deb hisoblanadi.</p>\r\n\r\n<p>2.1.9.&nbsp;Mehnat shartnomasi tuzilganidan keyin ish beruvchi mehnat shartnomasining mazmuniga muvofiq ravishda ishga qabul qilish to&lsquo;g&lsquo;risida buyruq chiqaradi va buyruq bilan imzo qo&lsquo;ydirgan holda xodimni tanishtiradi.</p>\r\n\r\n<p>2.1.10.&nbsp;Universitet quyidagi hollarda ishga qabul qilishdan bosh tortishga haqli emas:</p>\r\n\r\n<p>a) ish beruvchining o&lsquo;zi tomonidan ishga taklif qilingan shaxslar;</p>\r\n\r\n<p>b) nogironlar, o&lsquo;quv muassasalarning bitiruvchilari, uch va undan ortiq farzandlari bor yolg&lsquo;iz ota (ona), pensiya yoshiga yaqinlashgan shaxslar agar ular joylardagi davlat hokimiyati organi tomonidan muassasaga belgilangan eng kam miqdordagi ish o&lsquo;rinlari hisobidan ishga yo&lsquo;llanma bo&lsquo;yicha mahalliy mehnat organlari tomonidan yuborilgan bo&lsquo;lsa;</p>\r\n\r\n<p>v) homilador ayollar va uch yoshgacha bolalari bo&lsquo;lgan shaxslar;</p>\r\n\r\n<p>g) qonun hujjatlarida nazarda tutilgan boshqa hollarda.</p>\r\n\r\n<p>2.1.11.&nbsp;Xodim ish beruvchidan ishga qabul qilishni rad etish sabablarini yozma ravishda asoslashni talab qilishga haqlidir. Ish beruvchi uch kun ichida unga yozma asos ko&lsquo;rsatishi shart. Homilador ayollarga va uch yoshgacha bolasi bo&lsquo;lgan ayollarga ish beruvchining agar ular shunday talab bilan murojaat etmagan taqdirda</p>\r\n\r\n<p>ham ishga qabul qilishni rad etish sababi yozma ravishda tushuntiriladi. Ishga qabul qilish g&lsquo;ayriqonuniy ravishda rad etilganda xodim belgilangan tartibda nazorat qiluvchi organ yoki sudga shikoyat qilishga haqlidir.</p>\r\n\r\n<p>2.1.12.&nbsp;Ishga qabul qilish paytida mehnat shartnomasida dastlabki sinov to&lsquo;g&lsquo;risida shartlashilgan bo&lsquo;lishi mumkin. Bunday shartlashuv bo&lsquo;lmagan taqdirda xodim dastlabki sinovsiz ishga qabul qilingan deb hisoblanadi. Sinov to&lsquo;g&lsquo;risidagi shart ishga qabul qilish to&lsquo;g&lsquo;risidagi buyruqda aks ettiriladi. Dastlabki sinov bilan ishga qabul qilingan xodimning mehnat daftarchasiga ishga qabul qilish haqidagi yozuv dastlabki sinov haqidagi shartlar ko&lsquo;rsatilmagan holda kiritiladi.</p>\r\n\r\n<p>Dastlabki sinov muddati uch oydan oshib ketishi mumkin emas. Dastlabki sinovning aniq muddati (uch oy doirasida) mehnat shartnomasi taraflarining kelishuvi asosida belgilanadi. Taraflar tomonidan belgilangan sinov muddati tugagunga qadar ish beruvchi (sinov natijasi qoniqarsiz bo&lsquo;lgan taqdirda), shuningdek, xodim (mehnatga oid munosabatlarni davom ettirish istagi bo&lsquo;lmagan taqdirda) ikkinchi tarafni uch kun oldin yozma ravishda ogohlantirib, mehnat shartnomasini bekor qilishga haqli.</p>\r\n\r\n<p>Agar taraflar tomonidan belgilangan sinov muddati tugagunga qadar taraflardan birortasi mehnat shartnomasini bekor qilishni talab qilmasa, mehnat shartnomasining amal qilishi davom etadi va uni bundan keyin bekor qilishga umumiy asoslarda yo&lsquo;l qo&lsquo;yiladi.</p>\r\n\r\n<p>Xodimning vaqtincha mehnatga qobiliyatsizlik davri va uzrli sabablarga ko&lsquo;ra xodim ishda bo&lsquo;lmagan boshqa davrlar dastlabki sinov muddatiga kiritilmaydi.</p>\r\n\r\n<p>Dastlabki sinov davrida xodimga mehnat to&lsquo;g&lsquo;risidagi qonun hujjatlari va Universitet xodimlari uchun belgilangan mehnat shartlari to&lsquo;liq tatbiq etiladi.</p>\r\n\r\n<p>Xodimni boshqa ishga o&lsquo;tkazishda sinov muddati belgilanishiga yo&lsquo;l qo&lsquo;yilmaydi.</p>\r\n\r\n<p>Quyidagilar bilan mehnat shartnomasi tuzish davrida dastlabki sinov muddati qo&lsquo;llanilmaydi:</p>\r\n\r\n<p>homilador ayollar, shuningdek, 3 yoshga to&lsquo;lmagan bolasi bor ayollar;</p>\r\n\r\n<p>o&lsquo;rta maxsus, kasb-hunar ta&rsquo;limi muassasalari hamda oliy o&lsquo;quv yurtlarining tegishli ta&rsquo;lim muassasasini tamomlagan kundan e&rsquo;tiboran uch yil ichida birinchi bor ishga kirayotgan bitiruvchilar;</p>\r\n\r\n<p>olti oygacha muddatga ishga qabul qilinayotganlar;</p>\r\n\r\n<p>Universitet uchun belgilangan minimal ish joylari hisobidan ishga yuborilgan shaxslar.</p>\r\n\r\n<p>2.1.13.&nbsp;Universitetga ishga qabul qilish belgilangan tartibda tasdiqlangan nizom talablari asosida amalga oshiriladi.</p>\r\n\r\n<p>2.1.14.&nbsp;Ishga qabul qilish jarayonida yoki xodim uning roziligi bilan boshqa ishga o&lsquo;tkazilayotganda Universitet:</p>\r\n\r\n<p>unga yuklatilgan mehnat vazifalari doirasi, huquq va majburiyatlari, mehnat va mehnatga haq to&lsquo;lash shartlari;</p>\r\n\r\n<p>mazkur Qoidalar, jamoa shartnomasi, lavozim yo&lsquo;riqnomasi va xodimning mehnat faoliyatiga oid boshqa hujjatlar;</p>\r\n\r\n<p>Universitetning Odob-axloq kodeksi;</p>\r\n\r\n<p>Universitetning korrupsiyaga qarshi kurashish dasturi (siyosati) bilan;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Universitet xodim, talaba, o&lsquo;quvchi va doktorantlari tomonidan korrupsiyaviy huquqbuzarliklar sodir etishga og&lsquo;dirish maqsadida murojaat qilish holatlari haqida xabardor qilish to&lsquo;g&lsquo;risidagi nizom;</p>\r\n\r\n<p>mehnatni muhofaza qilish, texnika xavfsizligi va ishlab chiqarish sanitariyasiga doir qoidalar bilan xodimni tanishtirishi lozim.</p>\r\n\r\n<p>2.1.15.&nbsp;Universitetda besh kundan ortiq ishlagan barcha xodimlarga Kadrlar bo&lsquo;limi tomonidan Mehnat daftarchalarini yuritish tartibi to&lsquo;g&lsquo;risidagi yo&lsquo;riqnoma (ro&lsquo;yxat raqami 402, 1998 yil 29 yanvar) qoidalariga muvofiq mehnat daftarchasi yuritiladi, o&lsquo;rindoshlik asosida ishlovchilar bundan mustasno.</p>\r\n\r\n<p>Shuningdek, O&lsquo;zbekiston Respublikasi Vazirlar Mahkamasining<br />\r\n2019 yil 5 dekabrdagi 971-son qarori bilan tasdiqlangan &ldquo;Yagona milliy mehnat tizimi&rdquo; idoralararo dasturiy-apparat kompleksida mehnat shartnomalarini ro&lsquo;yxatdan o&lsquo;tkazish, elektron mehnat daftarchalarini shakllantirish va yuritish tartibi to&lsquo;g&lsquo;risidagi nizom talablariga asosan &ldquo;Yagona milliy mehnat tizimi&rdquo; idoralararo dasturiy-apparat kompleksida elektron mehnat daftarchalarini shakllantirish va yuritish ta&rsquo;minlanadi.</p>\r\n\r\n<p>2.1.16.&nbsp;Ish beruvchi va Universitetning mansabdor shaxslari xodimdan uning mehnat majburiyatlariga kirmaydigan ishlarni bajarish, qonunga zid harakatlarni sodir etish, shuningdek, xodimning yoki boshqa shaxslarning hayoti va sog&lsquo;lig&lsquo;ini xavf ostiga qo&lsquo;yadigan, or-nomusi va sha&rsquo;nini kamsitadigan harakatlar sodir etishni talab qilishga haqli emas.</p>\r\n\r\n<p>Universitetda xotin-qizlar bilan munosabatlar qonunchilik hujjatlari talablari, milliy an&rsquo;analar va o&lsquo;zaro hurmat tamoyillariga asoslanishi lozim.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>2.2.&nbsp;Mehnat shartnomasini o&lsquo;zgartirish va bekor qilish</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>2.2.1.&nbsp;Mehnat shartlarini o&lsquo;zgartirish O&lsquo;zbekiston Respublikasining Mehnat kodeksi talablari asosida amalga oshiriladi.</p>\r\n\r\n<p>2.2.2.&nbsp;Xodim bir necha kasb va lavozimdagi ishlarni mehnat shartnomasida ko&lsquo;rsatilgan o&lsquo;zining asosiy ishi bilan bir qatorda belgilangan ish vaqti davomida bajaradi.</p>\r\n\r\n<p>2.2.3.&nbsp;Bir necha kasb va lavozimda ishlash muayyan yoki nomuayyan muddatga belgilanishi mumkin. Kelishilgan muddat tugaganidan so&lsquo;ng bir necha kasb va lavozimda ishlash haqida mazkur xodim bilan belgilangan shartlar bekor qilinadi. Bir necha kasb va lavozimda ishlash va uni bekor qilish mehnat shartnomasida aks ettiriladi va Universitet rektorining buyrug&lsquo;i bilan rasmiylashtiriladi.</p>\r\n\r\n<p>2.2.4.&nbsp;Mehnat shartnomasi faqat O&lsquo;zbekiston Respublikasining Mehnat kodeksida nazarda tutilgan asoslar bo&lsquo;yicha va unda belgilangan tartibda bekor qilinishi mumkin.</p>\r\n\r\n<p>2.2.5.&nbsp;Xodim mehnat shartnomasini bekor qilish niyatida ekanligi haqida ikki hafta oldin ariza bilan ish beruvchini yozma ravishda ogohlantirishi shart. Ogohlantirish muddati ariza ro&lsquo;yxatga olingan sanadan qat&rsquo;i nazar, ariza berilgan kunning ertasidan boshlanadi.</p>\r\n\r\n<p>Xodim tomonidan berilgan ariza u berilgan kun va keyingi kundan kechiktirmay Universitet rektoriga taqdim etiladi.</p>\r\n\r\n<p>Xodimning arizasi uzrli sabablarga ko&lsquo;ra ishni davom ettirishning imkoni yo&lsquo;qligi bilan bog&lsquo;liq bo&lsquo;lsa, u berilgan kunda Universitet rektori (rektor bo&lsquo;lmaganda uning o&lsquo;rnini bosuvchi shaxs)ga taqdim etiladi.</p>\r\n\r\n<p>Quyidagilar uzrli sabablar jumlasiga kiradi:</p>\r\n\r\n<p>harbiy xizmatni o&lsquo;tash;</p>\r\n\r\n<p>o&lsquo;quv yurtlariga o&lsquo;qishga qabul qilinganlik;</p>\r\n\r\n<p>pensiyaga chiqqanlik;</p>\r\n\r\n<p>saylab qo&lsquo;yiladigan lavozimga saylanish yoki yuqori turuvchi idoralar nomenklaturasi (lavozimlar ro&lsquo;yxati)ga kiruvchi lavozimlarga tayinlanish;</p>\r\n\r\n<p>xodim yoki uning parvarishiga muhtoj bo&lsquo;lgan yaqin qarindoshlari sog&lsquo;ligining TMEK yoki TMK tomonidan berilgan tibbiy xulosaga muvofiq holati;</p>\r\n\r\n<p>ushbu lavozimda ishlashni davom ettirishning imkoni yo&lsquo;qligi to&lsquo;g&lsquo;risidagi boshqa uzrli sabablar.</p>\r\n\r\n<p>2.2.6.&nbsp;Xodim mehnat shartnomasini bekor qilish to&lsquo;g&lsquo;risida istalgan vaqtda, jumladan, vaqtinchalik mehnatga qobiliyatsizlik davri, ta&rsquo;til, xizmat safari davrida ariza berishga haqli. Sanab o&lsquo;tilgan ana shu davrlarning barchasi mehnat shartnomasini bekor qilish to&lsquo;g&lsquo;risidagi ogohlantirish muddati davriga kiritiladi.</p>\r\n\r\n<p>Ogohlantirish muddati davrida mehnat shartnomasining shartlari taraflar tomonidan odatdagi tartibda bajarilishi davom ettiriladi.</p>\r\n\r\n<p>2.2.7.&nbsp;Nomuayyan muddatga tuzilgan mehnat shartnomasi, shuningdek, muddatli mehnat shartnomasini ish beruvchining tashabbusiga ko&lsquo;ra uning muddati tugashidan oldin bekor qilishga quyidagi hollarda yo&lsquo;l qo&lsquo;yiladi:</p>\r\n\r\n<p>Universitet faoliyatida mehnatni tashkil etishdagi o&lsquo;zgarishlar, xodimlar soni (shtati) yoki ish xususiyatining o&lsquo;zgarishiga olib kelgan ishlar hajmi qisqarganda yoxud tegishli tarkibiy bo&lsquo;linmalar tugatilganda;</p>\r\n\r\n<p>xodimning malakasi etarli bo&lsquo;lmaganligi yoki sog&lsquo;lig&lsquo;i holatiga ko&lsquo;ra bajarayotgan ishiga noloyiq bo&lsquo;lib qolganda;</p>\r\n\r\n<p>xodim o&lsquo;z mehnat vazifalarini muntazam ravishda buzganda (avval mehnat majburiyatlarini buzganligi uchun xodim intizomiy yoki moddiy javobgarlikka tortilgan yoxud unga nisbatan mehnat to&lsquo;g&lsquo;risidagi qonunlar va boshqa normativ hujjatlarda nazarda tutilgan ta&rsquo;sir choralari qo&lsquo;llanilgan kundan e&rsquo;tiboran bir yil mobaynida xodim tomonidan takroran intizomga xilof nojo&lsquo;ya harakat sodir qilinishi mehnat vazifalarini muntazam ravishda buzish hisoblanadi);</p>\r\n\r\n<p>xodim o&lsquo;z mehnat vazifalarini bir marta qo&lsquo;pol ravishda buzganda;</p>\r\n\r\n<p>o&lsquo;rindoshlik asosida ishlamaydigan boshqa xodimning ishga qabul qilinishi munosabati bilan, shuningdek, mehnat shartlariga ko&lsquo;ra o&lsquo;rindoshlik ishi cheklanishi sababli o&lsquo;rindoshlar bilan mehnat shartnomasi bekor qilinganda;</p>\r\n\r\n<p>xodim pensiya yoshiga to&lsquo;lganda;</p>\r\n\r\n<p>qonun hujjatlariga muvofiq yoshga doir davlat pensiyasini olish huquqi mavjud bo&lsquo;lganda.</p>\r\n\r\n<p>2.2.8.&nbsp;Xodim vaqtincha mehnatga qobiliyatsizlik davrida va mehnat to&lsquo;g&lsquo;risidagi qonunlar va boshqa normativ hujjatlarda nazarda tutilgan ta&rsquo;tillarda bo&lsquo;lgan davrida mehnat shartnomasini ish beruvchining tashabbusi bilan bekor qilishga yo&lsquo;l qo&lsquo;yilmaydi, muassasa butunlay tugatilgan hollar bundan mustasno.</p>\r\n\r\n<p>2.2.9.&nbsp;Mehnat shartnomasini bekor qilishga olib kelishi mumkin bo&lsquo;lgan bir marta qo&lsquo;pol buzishga quyidagilar kiradi:</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>ijro intizomini buzish (O&lsquo;zbekiston Respublikasi Prezidentining qarorlari, farmonlari, farmoyishlari va topshiriqlarida, Hukumat qarorlari va farmoyishlari, Oliy ta&rsquo;lim, fan&nbsp;va&nbsp;innovatsiyalar&nbsp;vazirligi hay&rsquo;atining nodavlat ta&rsquo;lim muassasalariga tegishli qarorlari, buyruqlari va ko&lsquo;rsatmalarida belgilangan vazifalarni amalga oshirishni o&lsquo;z vaqtida va to&lsquo;liq hajmda ta&rsquo;minlamaganlik);</p>\r\n\r\n<p>ishga uzrli sabablarsiz kelmaslik (ishda uzrli sabablarsiz ish kuni mobaynida uzluksiz yoki ishda bo&lsquo;lmagan vaqtni jamlab hisoblaganda 3 (uch) soatdan ko&lsquo;proq vaqt bo&lsquo;lmaganlik), professor-o&lsquo;qituvchilar uchun dars jadvaliga ko&lsquo;ra bir ish kuni mobaynida dars jadvalida belgilangan dars mashg&lsquo;ulotlarini o&lsquo;z vaqtida boshlamaslik yoki ishtirok etmaslik;</p>\r\n\r\n<p>ishga alkogolli ichimlik, giyohvandlik (psixotrop) moddasi ta&rsquo;sirida yoki o&lsquo;zgacha tarzda mastlik holatida kelish;</p>\r\n\r\n<p>Universitetning mol-mulkiga zarar etkazish yoki uni turli xil usullar bilan talon-taroj qilish (shu jumladan, o&lsquo;g&lsquo;irlash);</p>\r\n\r\n<p>xodim tomonidan mansab (xizmat) vazifasi (vakolati)ni suiiste&rsquo;mol qilishi (lavozimi bo&lsquo;yicha berilgan vakolatlardan xizmat manfaatlariga zid ravishda foydalanish) va g&lsquo;ayriaxloqiy ko&lsquo;rinishdagi, Universitet xodimi degan nomga dog&lsquo; tushiruvchi xatti-harakatlarni sodir etish;</p>\r\n\r\n<p>xotin-qizlarga tegajog&lsquo;liq qilish, sha&rsquo;ni va qadr-qimmatini kamsitadigan harakatlar sodir etish, tazyiq o&lsquo;tkazish va zo&lsquo;ravonlik qilish, huquqlarini boshqacha tarzda poymol qilish;</p>\r\n\r\n<p>asossiz yoki g&lsquo;ayriaxloqiy xatti-harakatlari, OAV va ijtimoiy tarmoqlardagi chiqishlari bilan Universitetning ishchanlik obro&lsquo;si&nbsp;va manfaatlariga putur etkazish yoki zarar etkazishi mumkin bo&lsquo;lgan&nbsp;xatti-harakatlarni sodir etish;</p>\r\n\r\n<p>muassasa xodimlarining, jumladan, o&lsquo;zining hayoti yoki sog&lsquo;lig&lsquo;iga xavf tug&lsquo;diradigan tarzda texnika xavfsizligi, sanitariya qoidalarini qo&lsquo;pol ravishda buzish;</p>\r\n\r\n<p>xodimlar tomonidan vazifalarini bajarishda korrupsiyaga oid huquqbuzarliklar sodir etilishining oldini olish tartibi to&lsquo;g&lsquo;risidagi nizom talablarini qo&lsquo;pol ravishda buzish, ya&rsquo;ni xodim:</p>\r\n\r\n<p>uni korrupsiyaga oid huquqbuzarliklar sodir etishga ko&lsquo;ndirish maqsadida biror-bir shaxs o&lsquo;ziga murojaat etganligiga doir barcha hollar to&lsquo;g&lsquo;risida, shuningdek, davlat organlarining boshqa xodimlari tomonidan sodir etilgan shunga o&lsquo;xshash huquqbuzarliklarning o&lsquo;zlariga ma&rsquo;lum bo&lsquo;lib qolgan har qanday faktlari haqida o&lsquo;z rahbarlari yoxud huquqni muhofaza qiluvchi organlarni xabardor etmasligi;</p>\r\n\r\n<p>o&lsquo;z xizmat mavqeidan foydalangan holda yoki jismoniy va yuridik shaxslardan ularning manfaatlarini ko&lsquo;zlagan holda muayyan harakatni bajarishi yoki bajarmasligi evaziga bevosita o&lsquo;zi yoki vositachi orqali pul, qimmatli qog&lsquo;ozlar, moddiy boyliklar, sovg&lsquo;alar, ssudalar, mulkiy mohiyatga molik bo&lsquo;lgan xizmatlar olishi;</p>\r\n\r\n<p>bo&lsquo;ysunuvidagi xodimning noqonuniy qarorlar qabul qilish yoki korrupsiyaviy xatti-harakatlar sodir etishga majbur etishi;</p>\r\n\r\n<p>xizmat ko&lsquo;rsatilishi uchun fuqarolarga belgilangan to&lsquo;lovlardan mansabidan foydalangan holda ozod bo&lsquo;lish orqali mulkiy foyda olishi yoki boshqacha tarzda imtiyozlarga ega bo&lsquo;lishga qaratilgan harakatga yo&lsquo;l qo&lsquo;yishi;</p>\r\n\r\n<p>boshqaruv tartibiga qarshi jinoyatlar, jumladan, mansab yoki xizmat mavqeini suiiste&rsquo;mol qilish bilan bog&lsquo;liq hamda korrupsiyaning kelib chiqishiga sabab bo&lsquo;lishi</p>\r\n\r\n<p>mumkin bo&lsquo;lgan holatlar to&lsquo;g&lsquo;risida tegishli tarkibiy bo&lsquo;linma rahbariga xabar bermasligi;</p>\r\n\r\n<p>muassasa tomonidan o&lsquo;tkazilayotgan o&lsquo;rganish (tekshirish) guruhi rahbari o&lsquo;rganish (tekshirish)da qatnashayotgan xodimlar tomonidan mansab vakolatini suiiste&rsquo;mol qilish bilan bog&lsquo;liq xabar kelib tushgan taqdirda bu haqida yuqori turuvchi mansabdor shaxsga etkazmasa hamda salbiy oqibatlar kelib chiqishining oldini olish choralarini ko&lsquo;rmasa;</p>\r\n\r\n<p>xodimning ongli ravishda Universitetda manfaatlar to&lsquo;qnashuvini boshqarish to&lsquo;g&lsquo;risidagi nizomda belgilangan tartibda manfaatlar to&lsquo;qnashuvi to&lsquo;g&lsquo;risidagi ma&rsquo;lumotlarni qasddan yashirishi yoki o&lsquo;z vaqtida to&lsquo;liq oshkor qilmasligi natijasida xizmat majburiyatlarini lozim darajada bajarmasligiga olib kelsa yoki Universitetning qonuniy manfaatlari buzilsa.</p>\r\n\r\n<p>2.2.10.&nbsp;Ish beruvchi tomonidan mazkur Qoidalarning 2.2.9-bandida ko&lsquo;rsatilgan asoslarga ko&lsquo;ra xodim bilan tuzilgan mehnat shartnomasining Universitet Kasaba uyushmasi qo&lsquo;mitasi&nbsp;(agar kasaba uyushmasi qo&lsquo;mitasi&nbsp;tuzilgan bo&lsquo;lsa)&nbsp;roziligini olmasdan bekor qilinishiga yo&lsquo;l qo&lsquo;yilmaydi, qonunchilikda ko&lsquo;rsatilgan holatlar bundan mustasno.</p>\r\n\r\n<p>Kasaba uyushmasi qo&lsquo;mitasining&nbsp;(agar kasaba uyushmasi qo&lsquo;mitasi&nbsp;tuzilgan bo&lsquo;lsa)&nbsp;xodim bilan mehnat shartnomasini bekor qilishga rozilik berish masalasi bo&lsquo;yicha qabul qilgan qarori haqida ish beruvchiga yozma ravishda xabar berishi kerak, bunday xabar ish beruvchining yozma taqdimnomasi olingan kundan boshlab o&lsquo;n kunlik muddat ichida ma&rsquo;lum qilinadi.</p>\r\n\r\n<p>Ish beruvchi kasaba uyushmasi qo&lsquo;mitasining&nbsp;(agar kasaba uyushmasi qo&lsquo;mitasi&nbsp;tuzilgan bo&lsquo;lsa)&nbsp;xodim bilan mehnat shartnomasini bekor qilishga rozilik berish to&lsquo;g&lsquo;risidagi qarori qabul qilingan kundan boshlab bir oydan kechiktirmay mehnat shartnomasini bekor qilishga haqlidir.</p>\r\n\r\n<p>2.2.11.&nbsp;Mehnat shartnomasini bekor qilish ish beruvchining buyrug&lsquo;i bilan rasmiylashtiriladi.</p>\r\n\r\n<p>Oxirgi ish kuni mehnat shartnomasi bekor qilingan kun deb hisoblanadi. SHu kuni Universitet xodimga uning mehnat daftarchasi va mehnat shartnomasi bekor qilinganligi haqida buyruq nusxasini beradi hamda u bilan hisob-kitob qilinadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>3-bob.&nbsp;Ish vaqti, dam olish vaqti hamda ulardan foydalanish</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>3.1.&nbsp;Xodim ish tartibi yoki grafigiga yoxud mehnat shartnomasi shartlariga muvofiq o&lsquo;z mehnat vazifalarini bajarishi lozim bo&lsquo;lgan vaqt ish vaqti hisoblanadi.</p>\r\n\r\n<p>3.2.&nbsp;Universitet xodimlari uchun har kungi ish vaqtining boshlanishi va tamom bo&lsquo;lishi hamda dam olish va ovqatlanish uchun tanaffus vaqti quyidagicha belgilanadi:</p>\r\n\r\n<p>har kuni &ndash; soat 8.30 dan 16.30 gacha, 9.00-17.00 gacha;</p>\r\n\r\n<p>kundalik tushlik tanaffus &ndash; 13.00 dan 14.00 gacha.</p>\r\n\r\n<p>Shuningdek, professor-o&lsquo;qituvchilarning ish vaqti jamlab hisoblanadigan ish vaqti rejimida belgilanadi.</p>\r\n\r\n<p>Umumiy dam olish kuni &ndash; yakshanba.</p>\r\n\r\n<p>3.3.&nbsp;Zarurat tug&lsquo;ilganda ish kuni rejimi rektorining buyrug&lsquo;i bilan o&lsquo;zgartirilishi mumkin</p>\r\n\r\n<p>3.4.&nbsp;Professor-o&lsquo;qituvchilar uchun ish vaqtining qisqartirilgan vaqti<br />\r\nva ish kuni haftasiga 36 soatlik qilib belgilanadi hamda o&lsquo;quv mashg&lsquo;ulotlari jadvaliga ko&lsquo;ra tartibga solinadi.</p>\r\n\r\n<p>3.5.&nbsp;Professor-o&lsquo;qituvchilar faoliyatini ish kuni davomida barcha turdagi o&lsquo;quv, ilmiy-metodik, ilmiy-tadqiqot, tashkiliy-metodik, ma&rsquo;naviy-axloqiy va tarbiyaviy ishlar rejasi asosida amalga oshiradi.</p>\r\n\r\n<p>3.6.&nbsp;Professor-o&lsquo;qituvchilar tomonidan o&lsquo;quv mashg&lsquo;ulotlari jadvali, ish rejasi va navbatchilik jadvalining bajarilishi o&lsquo;quv ishlari bo&lsquo;yicha prorektor, tegishliligi bo&lsquo;yicha fakultet dekani va uning o&lsquo;rinbosari hamda kafedra mudiri tomonidan nazorat qilib boriladi.</p>\r\n\r\n<p>3.7.&nbsp;Quyidagi xodimlarga ham ish vaqtining qisqartirilgan muddati belgilanadi:</p>\r\n\r\n<p>16 yoshdan 18 yoshgacha bo&lsquo;lgan xodimlar &ndash; haftasiga 36 soat;</p>\r\n\r\n<p>I va II guruh nogironlari &ndash; haftasiga 36 soat.</p>\r\n\r\n<p>3.8.&nbsp;Xodim bilan ish beruvchi o&lsquo;rtasidagi kelishuvga binoan ishga qabul qilish chog&lsquo;ida ham, keyinchalik ham to&lsquo;liqsiz ish kuni yoki to&lsquo;liqsiz ish haftasi, masofaviy ish usuli, moslashuvchan ish jadvali yoki uyda ishlash rejimiga o&lsquo;tkazish belgilab qo&lsquo;yilishi mumkin.</p>\r\n\r\n<p>Ish beruvchi homilador ayolning, 14 yoshga to&lsquo;lmagan (16 yoshga to&lsquo;lmagan nogiron) bolasi bor ayolning, jumladan, homiyligida shunday bolasi bor ayolning yoki oilaning betob a&rsquo;zosini parvarish qilish bilan band bo&lsquo;lgan shaxsning iltimosiga ko&lsquo;ra, tibbiy xulosaga muvofiq, shuningdek, qonun hujjatlarida nazarda tutilgan boshqa hollarda ularga to&lsquo;liqsiz ish vaqti belgilaydi.</p>\r\n\r\n<p>3.9.&nbsp;Ish vaqtidan tashqari xodimlarni ishga jalb etish qonun hujjatlarida belgilangan tartibda amalga oshiriladi.</p>\r\n\r\n<p>3.10.&nbsp;Yillik ta&rsquo;tillarning muddati, ular uchun haq to&lsquo;lash va ularni hisoblab chiqarish, shuningdek, ta&rsquo;til olish huquqini beradigan ish stajini hisoblab chiqarish qonun hujjatlarida nazarda tutilgan tartibda amalga oshiriladi.</p>\r\n\r\n<p>3.11.&nbsp;Xodimning arizasiga binoan unga ish haqi saqlanmagan holda ta&rsquo;til berilishi mumkin, uning muddati tomonlarning kelishuviga binoan belgilanadi, lekin u o&lsquo;n ikki oylik davr mobaynida jami uch oydan ortiq bo&lsquo;lmasligi kerak.</p>\r\n\r\n<p>3.12.&nbsp;Har yilgi asosiy ta&rsquo;til quyidagicha beriladi:</p>\r\n\r\n<p>birinchi ish yili uchun olti oy ishlagandan keyin (qonunda ko&lsquo;rsatilgan holatlar bundan mustasno);</p>\r\n\r\n<p>ikkinchi va undan keyingi ish yillari uchun ta&rsquo;tillar jadvaliga muvofiq ish yilining istalgan vaqtida (qonunda ko&lsquo;rsatilgan holatlar bundan mustasno).</p>\r\n\r\n<p>Ta&rsquo;tildan foydalanishning jadvalda belgilangan vaqti xodim bilan ish beruvchining kelishuviga binoan o&lsquo;zgartirilishi mumkin.</p>\r\n\r\n<p>3.13.&nbsp;Xodimning yozma arizasiga binoan ta&rsquo;til qismlarga bo&lsquo;linishi mumkin. Bunda ta&rsquo;tilning bir qismi o&lsquo;n ikki ish kunidan kam bo&lsquo;lmasligi lozim.</p>\r\n\r\n<p>3.14.&nbsp;Ta&rsquo;tildan chaqirib olishga faqat xodimning roziligi bilan yo&lsquo;l qo&lsquo;yiladi. Ta&rsquo;tilning foydalanilmay qolgan qismi xodimga mazkur ish yilida beriladi yoki ta&rsquo;tilni boshqa muddatga ko&lsquo;chirish qoidalariga rioya etilgan holda keyingi yilga ko&lsquo;chiriladi.</p>\r\n\r\n<p>3.15.&nbsp;Xodimlarning xohishiga ko&lsquo;ra yillik ta&rsquo;tilning eng kam muddatidan (o&lsquo;n besh ish kunidan) ortiqcha qismi uchun pullik kompensatsiya to&lsquo;lanishi mumkin.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Ta&rsquo;til berish vaqti haqida xodim ta&rsquo;til boshlanishidan kamida o&lsquo;n besh kun oldin xabardor qilinishi kerak.</p>\r\n\r\n<p>Ta&rsquo;til uchun haq to&lsquo;lash ta&rsquo;til boshlanmasidan oldingi oxirgi ish kunidan kechikmay amalga oshirilishi lozim.</p>\r\n\r\n<p>3.16.&nbsp;Mehnat shartnomasi bekor qilinganda, jumladan, uning muddati tamom bo&lsquo;lishi munosabati bilan ham, xodimning xohishiga ko&lsquo;ra, xodim bilan ish beruvchi o&lsquo;rtasidagi kelishuvga muvofiq yillik ta&rsquo;tillarni berib, undan keyin mehnat shartnomasini bekor qilish hollari nazarda tutilishi mumkin. Bu holda ta&rsquo;til tugagan kun mehnat shartnomasi bekor qilingan kun deb hisoblanadi.</p>\r\n\r\n<p>Mazkur bandda nazarda tutilgan ta&rsquo;til davrida xodim mehnat shartnomasi va uning tashabbusi bilan bekor qilish to&lsquo;g&lsquo;risidagi arizasini basharti mehnat shartnomasini bekor qilish to&lsquo;g&lsquo;risida ogohlantirishning qonun yoki taraflarning kelishuvi bilan belgilangan muddati tugagan bo&lsquo;lsa, qaytarib olishga haqli emas.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>4-bob.&nbsp;Ta&rsquo;limni tashkil etish tartibi, mehnat va o&lsquo;quv intizomi</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>4.1.&nbsp;Universitetda o&lsquo;quv yili o&lsquo;quv grafigida belgilangan sanadan&nbsp; boshlanadi. O&lsquo;quv mashg&lsquo;ulotlari o&lsquo;quv reja va o&lsquo;quv dasturlariga mos ravishda tuzilgan dars jadvallariga asosan olib boriladi.</p>\r\n\r\n<p>4.2.&nbsp;O&lsquo;quv mashg&lsquo;ulotlari dars jadvali elektron Universitet ta&rsquo;lim platformasida semestr uchun tuzilib, tegishli tartibda tasdiqlanadi va semestr boshlanishidan oldin talabalar, professor-o&lsquo;qituvchilar, fakultet dekanatlari va boshqa tuzilmalarga yuboriladi. Fakultativ mashg&lsquo;ulotlar alohida jadval asosida o&lsquo;quv jarayoniga kiritilishi mumkin.</p>\r\n\r\n<p>4.3.&nbsp;Dars jadvali semestr uchun tuziladi va semestr boshlanishidan 10 kundan kechiktirmay osib qo&lsquo;yiladi. Fakultativ mashg&lsquo;ulotlar o&lsquo;tkazish uchun alohida jadval tuziladi.</p>\r\n\r\n<p>4.4. Akademik soatning davomiyligi 40 minut (tanaffussiz qo&lsquo;shma dars 80 minut). O&lsquo;quv mashg&lsquo;uloti boshlanishi va tugashi haqida o&lsquo;qituvchi va talabalar qo&lsquo;ng&lsquo;iroq bilan ogohlantiriladi. Har juftlik mashg&lsquo;ulot o&lsquo;rtasida 10 minut tanaffus belgilanadi.</p>\r\n\r\n<p>4.5. O&lsquo;quv kuni davomida tushlik tanaffus 40 minutdan oshmasligi&nbsp; kerak. Dars boshlangandan keyin barcha o&lsquo;quv xonalarida tinchlik va tartib ta&rsquo;minlanishi lozim. O&lsquo;quv mashg&lsquo;ulotlarini bo&lsquo;lish, dars paytida auditoriyaga sababsiz kirish va chiqib ketishga yo&lsquo;l qo&lsquo;yilmaydi.</p>\r\n\r\n<p>4.6. Har bir o&lsquo;quv mashg&lsquo;uloti boshlangunga qadar (mashg&lsquo;ulotlar orasidagi tanaffus paytida) auditoriya, laboratoriya, o&lsquo;quv ustaxonalari va kabinetlarida laborantlar zarur o&lsquo;quv qo&lsquo;llanmalar va uskunalarni darsga tayyorlaydilar.</p>\r\n\r\n<p>4.7. Amaliy va seminar mashg&lsquo;ulotlari bir akademik gurux uchun bir o&lsquo;quv auditoriyasida o&lsquo;tkaziladi, laboratoriya mashg&lsquo;ulotlari&nbsp;&nbsp; har bir akademik gurux 15 talabadan ko&lsquo;p bulmagan guruxchalarga bo&lsquo;lingan xolda o&lsquo;tkaziladi. Talabalar guruhchalarining tarkibi mashg&lsquo;ulotlar xarakteridan kelib chiqib semestr boshida fan o&lsquo;qituvchisi tomonidan belgilanadi.</p>\r\n\r\n<p>4.8. O&lsquo;quv yili ikki semestrga bo&lsquo;linadi va har o&lsquo;quv semestri yakuniy nazoratlar sessiyasi bilan yakunlanadi. Yakuniy nazoratlar sessiyasida axamiyati baland bo&lsquo;lgan 5 tagacha fandan yakuniy nazorat topshiriladi. Semestrda o&lsquo;tilgan qolgan fanlardan semestr oxirigacha joriy nazoratlar topshiriladi. Yakuniy nazoratlar</p>\r\n\r\n<p>sessiyasiga o&lsquo;quv rejasida semestr uchun nazarda tutilgan joriy nazoratlarning hammasini muvaffaqiyatli topshirgan talabalar qo&lsquo;yiladi.</p>\r\n\r\n<p>4.9. O&lsquo;quv rejasidagi fanlardan joriy va yakuniy nazoratlarni muvaffaqiyatli toshirgan va talab qilingan&nbsp;GPA&nbsp;ko&lsquo;rsatgichiga erishgan talabalar rektor buyrugi bilan keyingi kursga o&lsquo;tkaziladi. Bir yoki bir necha fandan qarzdorligi bo&lsquo;lgan talabalar ularni kuzgi semestr oxiridan, yoki baxorgi semestr boshlanishidan keyin 30 kun davomida bartaraf qilishlari zarur.&nbsp; Talab qilingan&nbsp;GPA&nbsp;ko&lsquo;rsatgichiga erishaolmagan talabalar Universitet rektori buyrugi bilan kursidan qoldiriladi.</p>\r\n\r\n<p>4.10.&nbsp;Universitet jamoat, tashkiliy va ma&rsquo;muriy ishlarni bajarishda ko&lsquo;maklashish, talabalarning o&lsquo;zini o&lsquo;zi boshqarish tizimini samarali yo&lsquo;lga qo&lsquo;yish uchun fakultet dekanati tomonidan guruh sardorlari ular saylangunga qadar vaqtinchalik vazifasini bajarish uchun tayinlanadi.</p>\r\n\r\n<p>Guruh sardorlari o&lsquo;zining ish faoliyatini Universitet Ustavi, mazkur Qoidalar, Universitetning boshqa ichki lokal hujjatlari asosida olib boradi. Guruh sardorlari guruh murabbiyi (tyutori)ning tavsiyasiga ko&lsquo;ra guruhning umumiy yig&lsquo;ilishida ochiq ovoz berish yo&lsquo;li bilan saylanadi. Birinchi kursda guruh sardorlari fakultet dekani tomonidan vaqtinchalik vazifasini bajarishga tayinlanadi, keyinchalik bir oy ichida guruhning umumiy yig&lsquo;ilishida ochiq ovoz berish yo&lsquo;li bilan saylanadi.</p>\r\n\r\n<p>4.11.&nbsp;Guruh sardori o&lsquo;z arizasiga muvofiq yoki zimmasiga yuklatilgan vazifalarni talab darajasida bajarmaganligi, guruh sardori obro&lsquo;siga putur etkazadigan xatti-harakatlarni sodir etganligi uchun fakultet dekanining taqdimiga ko&lsquo;ra muddatidan oldin vazifasidan ozod etilishi mumkin.</p>\r\n\r\n<p>4.12. Guruh sardorining vazifasiga quyidagilar kiradi:</p>\r\n\r\n<p>a)&nbsp; o&lsquo;quv&nbsp; mashg&lsquo;ulotlarining hamma turlari bo&lsquo;yicha talabalarni shaxsan hisobga olish;</p>\r\n\r\n<p>b) har kuni fakultet dekaniga darsga kelmagan va kechikkan talabalar to&lsquo;g&lsquo;risida, ularning sabablarini ko&lsquo;rsatgan holda ma&rsquo;lumot berish;</p>\r\n\r\n<p>v) ma&rsquo;ruza va amaliy mashg&lsquo;ulot darslarida guruhda o&lsquo;quv fanining borishini kuzatish, shuningdek, o&lsquo;quv uskunalari va jihozlarning saqlanishi haqida javobgarlik;</p>\r\n\r\n<p>g) guruh talabalari o&lsquo;rtasida darslik, o&lsquo;quv qo&lsquo;llanmalarini o&lsquo;z vaqtida olish va tarqatishni tashkil qilish;</p>\r\n\r\n<p>d) fakultet dekani tomonidan mashg&lsquo;ulotlar jadvaliga kiritilgan o&lsquo;zgarishlarni talabalarga etkazish;</p>\r\n\r\n<p>e) har kuni tartib bo&lsquo;yicha guruh navbatchisini belgilash;</p>\r\n\r\n<p>yo)o&lsquo;quv-tarbiyaviy ishlarni takomillashtirish yuzasidan fakultet dekanatiga takliflar kiritish;</p>\r\n\r\n<p>j)professor-o&lsquo;qituvchilar tomonidan o&lsquo;tkazilayotgan o&lsquo;quv mashg&lsquo;ulotlari sifati va talabalarning bilimini ob&rsquo;ektiv baholash yuzasidan talabalarning fikr-mulohazalarini fakultet dekanatiga etkazish.</p>\r\n\r\n<p>Hamma guruh talabalari uchun guruh sardorning yuqorida ko&lsquo;rsatilgan vazifalari&nbsp; dekanning&nbsp; buyrug&lsquo;i asosida etkaziladi.</p>\r\n\r\n<p>4.13. Har bir akademik guruh uchun belgilangan shakldagi guruh jurnali shakllantirilib, unda barcha darslar bo&lsquo;yicha darsga kelmagan talabalar guruh sardori tomonidan belgilab boriladi. Mazkur jurnal dekanatda saqlanadi. Har kunlik darslar boshlanishi oldidan guruh sardori dekanatdan jurnalni olib, shu kuni darslar tugagach, dekanatga topshiradi.</p>\r\n\r\n<p>Auditoriya, laboratoriya va o&lsquo;quv xonalaridagi jihozlar va boshqa ashyolar butligi, mavjudligi va yaroqli holdaligi uchun guruhning barcha talabalari moddiy javobgardirlar.</p>\r\n\r\n<p>4.14. Universitetda o&lsquo;quv jarayoni sifati va samaradorligini oshirish, davlat ta&rsquo;lim standartlari, malaka talablari, o&lsquo;quv rejalar, fan dasturlari, ishchi o&lsquo;quv rejalar va ishchi fan dasturlarining to&lsquo;laqonli bajarilishi, shuningdek, talabalarning chuqur bilim olishlari uchun ularga qulay shart-sharoit yaratib berish maqsadida quyidagicha tartib joriy etiladi:</p>\r\n\r\n<p>- dars boshlanganidan to yakunlanguniga qadar auditoriyaga turli shaxslar &ndash; Universitet rektori, prorektorlar, rektor maslahatchisi, bo&lsquo;lim boshliqlari, dekanlar va ularning o&lsquo;rinbosarlari, uslubchi yoki boshqa xodimlar, nazorat inspeksiyalari inspektorlari, shuningdek vazirlik va idoralar hamda mulkchilik shaklidan qat&rsquo;iy nazar har qanday darajadagi davlat va jamoat tashkilotlari yoki xokimliklar vakillaridan iborat o&lsquo;rganuvchilar (keyingi o&lsquo;rinlarda matnda - o&lsquo;rganuvchilar)ning kirishiga yo&lsquo;l qo&lsquo;yilmaydi;</p>\r\n\r\n<p>- o&lsquo;rganuvchilar Universitetga tegishli buyruq yoki ko&lsquo;rsatmalar asosida, rektor ruxsati bilangina kirishlari mumkin va bunda rektor o&lsquo;rganuvchilarning shaxsi va lavozimini tasdiqlovchi hujjatini so&lsquo;rashi, shaxsning kimligi va kelishdan maqsadi haqida to&lsquo;liq ma&rsquo;lumotga ega bo&lsquo;lib, qat&rsquo;iy ishonch hosil qilganidan so&lsquo;nggina ruxsat berishi lozim;</p>\r\n\r\n<p>- vazirlik va idoralar hamda har qanday darajadagi davlat va jamoat tashkilotlari vakillari tomonidan tashkil etiladigan barcha turdagi o&lsquo;rganishlar darsdan tashqari vaqtlarda &ndash; guruhlardagi kunlik mashg&lsquo;ulotlar boshlanishidan avval yoki yakunlanganidan keyin amalga oshirilishi mumkin;</p>\r\n\r\n<p>- turli mavzulardagi ma&rsquo;naviy-ma&rsquo;rifiy va madaniy tadbirlarni dars mashg&lsquo;ulotlari vaqtida o&lsquo;tkazilishiga hamda talabalarni darsdan tadbirga olib chiqib ketilishiga yo&lsquo;l qo&lsquo;yilmaydi va shu munosabat bilan barcha turdagi tadbirlarni darsdan avval yoki keyin o&lsquo;tkazish qat&rsquo;iy belgilab qo&lsquo;yiladi (boshqa turdagi yuqori darajali tadbirlarga jalb etilgan talabalarga dekanat ruxsat berishi va fan o&lsquo;qituvchilari ogohlantirilishi lozim);</p>\r\n\r\n<p>- professor-o&lsquo;qituvchilar o&lsquo;zaro dars kuzatish uchun, o&lsquo;rganuvchilar darslarning sifati va professor-o&lsquo;qituvchining faolligini o&lsquo;rganish uchun darslarda ishtirok etishlari avvaldan belgilangan reja asosida, mashg&lsquo;ulot o&lsquo;tkazayotgan professor-o&lsquo;qituvchini xabardor qilgan holda amalga oshiriladi. Ular auditoriyaga dars boshlanishidan avval kirgan bo&lsquo;lishlari, dars jarayonida fikr bildirib, darsga halaqit bermasliklari hamda darsdan mashg&lsquo;ulot tamomlanganidan so&lsquo;ng chiqishlari lozim;</p>\r\n\r\n<p>- mashg&lsquo;ulot davomida zarur bo&lsquo;ladigan barcha jihoz va vositalar auditoriyaga dars boshlanguniga qadar olib kirilgan bo&lsquo;lishi shart;</p>\r\n\r\n<p>- dars kuzatish yoki professor-o&lsquo;qituvchining faoliyatini o&lsquo;rganishga kirgan shaxs tomonidan professor-o&lsquo;qituvchining ruxsatisiz talabalarga savollar berish, ular bilan suhbatlashish, mashg&lsquo;ulotga aralashish, professor-o&lsquo;qituvchining metodik materiallarini ko&lsquo;rib chiqish yoki tekshirish, mashg&lsquo;ulotni video va auditasmalarga yozib olish, suratga olish hamda mobil aloqa vositalardan foydalanish, mashg&lsquo;ulot turi va shaklini o&lsquo;zgartirishga urinish kabi hollatlarga yo&lsquo;l qo&lsquo;yilmaydi;</p>\r\n\r\n<p>- dars mashg&lsquo;ulotlarida akademik guruh talabalari tarkibiga kirmaydigan shaxslarning ishtirok etishi faqat fakultet dekanining yozma ruxsati bilan amalga oshiriladi;</p>\r\n\r\n<p>- dars mashg&lsquo;ulotlaridan uzrsiz sabablarga ko&lsquo;ra chiqib ketgan talabalar darsga kelmagan deb hisoblansin;</p>\r\n\r\n<p><a name=\"3317706\">-&nbsp; dars mashg&lsquo;uloti ketayotgan vaqtda professor-o&lsquo;qituvchi yoki talabani darsdan chaqirib olish qat&rsquo;iyan man etiladi (favqulodda vaziyatlar bundan mustasno).</a></p>\r\n\r\n<p>4.15.&nbsp;Universitet rahbari xodimlari, professor-o&lsquo;qituvchilari va boshqa xodimlari va talabalari mazkur Qoidalar, Universitet Ustavi, Universitetning Odob-axloq kodeksi, Universitetning korrupsiyaga qarshi kurashish dasturi (siyosati), Universitet xodim, talaba, o&lsquo;quvchi va doktorantlari tomonidan korrupsiyaviy huquqbuzarliklar sodir etishga og&lsquo;dirish maqsadida murojaat qilish holatlari haqida xabardor qilish to&lsquo;g&lsquo;risidagi nizom, Universitet Kengashi qarorlari, rektor buyruqlari, lavozim yo&lsquo;riqnomasi, tarkibiy bo&lsquo;linmalar to&lsquo;g&lsquo;risidagi nizomlar va boshqa lokal normativ hujjatlarda belgilangan talablarga qat&rsquo;iy rioya etishlari shart.</p>\r\n\r\n<p>4.16.&nbsp;Mazkur Qoidalarning 62-bandida ko&lsquo;rsatilgan talablardan tashqari:</p>\r\n\r\n<p>a) xodimlar va talabalar:</p>\r\n\r\n<p>talaba o&lsquo;quv mashg&lsquo;ulotlariga uzrli sabablarga ko&lsquo;ra qatnasha olmagan holda bu haqida darhol fakultet dekanini xabardor qilib, asoslantiruvchi hujjatlarni taqdim etish;</p>\r\n\r\n<p>Universitet faoliyat samaradorligiga daxldor bo&lsquo;lish hamda uning rahbariyati (rektor,&nbsp;rektor maslahatchisi, prorektor, fakultet dekanlari, kafedra mudirlari, tarkibiy bo&lsquo;linma rahbarlari) haqida ma&rsquo;lumotga ega bo&lsquo;lish;</p>\r\n\r\n<p>uzrli sabablarga ko&lsquo;ra ish (o&lsquo;qish)ga kelmagan xodim (talaba) tarkibiy bo&lsquo;linma rahbari (fakultet dekani) yoki Kadrlar bo&lsquo;limini ogohlantirish hamda ish (o&lsquo;qish)ga chiqqan kuni asoslantiruvchi hujjatlarni taqdim etish;</p>\r\n\r\n<p>texnika xavfsizligi, ishlab chiqarish sanitariyasi, yong&lsquo;indan saqlash qoidalari va me&rsquo;yorlariga rioya etish;</p>\r\n\r\n<p>Universitet rahbariyatining roziligisiz o&lsquo;quv binosi va auditoriyalarga turli jihozlarni, begona shaxslarni olib kirmaslik va olib chiqmaslik;</p>\r\n\r\n<p>b) doktorant (mustaqil izlanuvchi va izlanuvchilar):</p>\r\n\r\n<p>O&lsquo;zbekiston Respublikasi Vazirlar Mahkamasining 2017 yil<br />\r\n22 maydagi 304-son qarori bilan tasdiqlangan Oliy o&lsquo;quv yurtidan keyingi ta&rsquo;limga qo&lsquo;yiladigan davlat talablari va Oliy o&lsquo;quv yurtidan keyingi ta&rsquo;lim to&lsquo;g&lsquo;risidagi nizom qoidalariga qat&rsquo;iy rioya qilish;</p>\r\n\r\n<p>doktorlik dissertatsiya ishini tayyorlashning yakka tartibdagi ish rejasiga ega bo&lsquo;lish va uni to&lsquo;liq hamda o&lsquo;z vaqtida bajarish;</p>\r\n\r\n<p>doktorlik dissertatsiyasini muddatida tayyorlash va Ilmiy kengashga himoya uchun taqdim etish;</p>\r\n\r\n<p>biriktirilgan tarkibiy bo&lsquo;linma bilan doimiy aloqada bo&lsquo;lish, tarkibiy bo&lsquo;linmaning faoliyati yo&lsquo;nalishi bilan bog&lsquo;liq ishlarda ishtirok etish;</p>\r\n\r\n<p>Universitetda haftasiga 20 soat bo&lsquo;lish (xizmat safari hamda ruxsat etilgan xorij safarlarida bo&lsquo;lish, aloqa xatlariga asosan boshqa tashkilotlarda tadqiqot olib borish bundan mustasno);</p>\r\n\r\n<p>Universitet va boshqa muassasalarda o&lsquo;tkaziladigan anjumanlarda ishtirok etish, shuningdek, boshqa mutasaddi tashkilotlardan kelgan ilmiy tadqiqotlar</p>\r\n\r\n<p>bo&lsquo;yicha hujjatlar ijrosini ta&rsquo;minlash va qonun loyihalarini tayyorlashda ishtirok etish;</p>\r\n\r\n<p>Universitet rektori, rektor maslahatchisi, prorektorlar, fakultet dekanlari hamda tegishli tarkibiy bo&lsquo;linmalarning rahbarlari tomonidan berilgan topshiriqlarni o&lsquo;z vaqtida va sifatli bajarish;</p>\r\n\r\n<p>davlat, jamiyat va jamoat manfaatlariga doir harakatlar qilganda, vaqtincha mehnatga layoqatsiz bo&lsquo;lganda, akademik ta&rsquo;til olish uchun asoslar vujudga kelganda hamda boshqa uzrli sabablar mavjudligida bo&lsquo;ysunuv tartibida yuqori turuvchi rahbarni xabardor qilishga majbur.</p>\r\n\r\n<p>4.17.&nbsp;To&lsquo;lov-kontrakt asosida ta&rsquo;lim olayotgan talabalarni moddiy jihatdan qo&lsquo;llab-quvvatlash qonun hujjatlarida belgilangan tartibda amalga oshirilishi mumkin.</p>\r\n\r\n<p>4.18.&nbsp;Universitetga xorijdan hamda respublikaning uzoq shahri va viloyatlaridan kelib ta&rsquo;lim olayotgan talabalar belgilangan mezonlar asosida komissiya xulosasiga ko&lsquo;ra hamda Universitet rektorining tegishli buyrug&lsquo;iga asosan Talabalar turar joylariga joylashtiriladi.</p>\r\n\r\n<p>4.19.&nbsp;Talabalar turar joylariga joylashish uchun talaba ariza bilan murojaat qiladi hamda tegishli hujjatlarni ilova qiladi. Mazkur murojaat o&lsquo;rnatilgan tartibda Universitet rektorining buyrug&lsquo;i bilan tasdiqlangan komissiya tomonidan hamda belgilangan mezonlar asosida ko&lsquo;rib chiqiladi.</p>\r\n\r\n<p>4.20.&nbsp;Talabalar turar joylarida istiqomat qiluvchi talabalar, qoida tariqasida, belgilangan tartibda vaqtincha hisobga olinadi.</p>\r\n\r\n<p>4.21.&nbsp;Talabalar turar joylarida istiqomat qiluvchi talabalar Talabalar turar joylari to&lsquo;g&lsquo;risidagi nizom, mazkur Qoidalar hamda Talabalar turar joylari xona va jihozlaridan foydalanish bo&lsquo;yicha lokal hujjat va shartnomalarda belgilangan huquqlarga ega bo&lsquo;ladi va majburiyatlarni bajaradi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>5-bob.&nbsp;Binolar ichidagi tartib</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>5.1. Bino ichiga kirish xizmat ruxsatnomalari, elektron ruxsatnoma, vaqtinchalik ruxsatnoma va talabalik guvohnomalari hamda shaxsni tasdiqlovchi boshqa hujjatlar asosida amalga oshiriladi.</p>\r\n\r\n<p>5.2.&nbsp;Ish vaqti tugagandan so&lsquo;ng xona va auditoriyalarning kaliti bino xavfsizligini ta&rsquo;minlovchi Universitetga biriktirilgan qo&lsquo;riqlash xizmati xodimiga maxsus jurnalga imzo qo&lsquo;yish orqali topshiriladi.</p>\r\n\r\n<p>5.3.&nbsp;Bino xavfsizligini ta&rsquo;minlovchi Universitetga biriktirilgan qo&lsquo;riqlash xizmati xodimi ish vaqti tugagandan so&lsquo;ng yong&lsquo;in va texnika xavfsizligini ta&rsquo;minlash maqsadida elektr yoritkichlar o&lsquo;chirilganligi, deraza va eshiklar qulflanganligi, xodim va talabalarning o&lsquo;z vaqtida binodan chiqib ketganligini tekshirib chiqadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>6-bob.&nbsp;Ish va o&lsquo;qishdagi yutuqlari uchun rag&lsquo;batlantirish</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>6.1.&nbsp;Xodimlar quyidagi shakllarda rag&lsquo;batlantiriladi:</p>\r\n\r\n<p>davlat va jamiyat oldidagi alohida xizmatlari uchun davlat mukofotlariga tavsiya etish to&lsquo;g&lsquo;risida bo&lsquo;ysunuvchi idora yoki Oliy ta&rsquo;lim, fan&nbsp;va&nbsp;innovatsiyalar&nbsp;vazirligiga taklif kiritish;</p>\r\n\r\n<p>mehnat faoliyatida alohida o&lsquo;rnak ko&lsquo;rsatayotganligi uchun faxriy yorliqlar va boshqa turdagi mukofotlarga tavsiya etish;</p>\r\n\r\n<p>Universitet faoliyati samaradorligiga munosib hissa qo&lsquo;shib belgilangan topshiriqlarni o&lsquo;z vaqtida bajarib kelayotgan xodim va talabalarni Universitet rektorining faxriy yorlig&lsquo;i hamda turli nominatsiyadagi diplomlari bilan taqdirlash;</p>\r\n\r\n<p>yubiley sanalari munosabati bilan moddiy rag&lsquo;batlantirish, sovg&lsquo;alar berish;</p>\r\n\r\n<p>kasb bayrami munosabati bilan bir yo&lsquo;la beriladigan mukofotlar;</p>\r\n\r\n<p>bayram sanalari munosabati bilan beriladigan mukofotlar va boshqa shakllardagi rag&lsquo;batlantirish choralari.</p>\r\n\r\n<p>6.2.&nbsp;Ish haqi, qo&lsquo;shimcha to&lsquo;lovlar, ustamalar va mehnatga oid qonun hujjatlarida nazarda tutilgan boshqa to&lsquo;lovlar mazkur Qoidalarda belgilangan rag&lsquo;batlantirish turlariga kirmaydi.</p>\r\n\r\n<p>6.3.&nbsp;Talabalar o&lsquo;qishda yuqori ko&lsquo;rsatkichlarga erishganligi, ilmiy-tadqiqot ishlari va Universitet ijtimoiy hayotida faol ishtiroki uchun quyidagi tartibda rag&lsquo;batlantiriladi:</p>\r\n\r\n<p>tashakkurnoma e&rsquo;lon qilish;</p>\r\n\r\n<p>pul mukofoti yoki qimmatbaho sovg&lsquo;a bilan taqdirlash;</p>\r\n\r\n<p>faxriy yorliq, darajali va turli nominatsiyali diplomlar bilan taqdirlash.</p>\r\n\r\n<p>Shu bilan birga, talabalarni moddiy rag&lsquo;batlantirish jamg&lsquo;armasi hisobidan to&lsquo;lov-kontrakt asosida ta&rsquo;lim olayotgan alohida iqtidorga ega, xalqaro, respublika va Universitet miqyosida o&lsquo;tkazilgan fan olimpiadalari va sport musobaqalari g&lsquo;oliblari, shuningdek, Universitet kengashi tomonidan belgilangan mezonlarga muvofiq alohida hollarda (ota-onasining vafoti, nogironligi, ijtimoiy himoyaga muhtojligi) talabalarga bazaviy stipendiyaga nisbatan ........ baravargacha miqdorda bo&lsquo;lgan bir martalik rag&lsquo;batlantirish yoki moddiy yordam to&lsquo;lovi berilishi mumkin.</p>\r\n\r\n<p>6.4.&nbsp;Talabalarni rag&lsquo;batlantirish Universitetning prorektori, rektor yordamchisi, fakultet dekanlari taqdimnomasi yoki tavsiyanomasi, Stipendiya komissiyasi qarori asosida Universitet rektorining buyrug&lsquo;iga muvofiq amalga oshiriladi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>7-bob.&nbsp;Mehnat va o&lsquo;quv intizomini buzganlik uchun javobgarlik</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>7.1.&nbsp;Universitet xodimga mehnat intizomini birinchi marta buzgani uchun yoki huquqbuzarlikni ehtiyotsizlikdan sodir etgan taqdirda quyidagi ta&rsquo;sir choralarini qo&lsquo;llashi mumkin:</p>\r\n\r\n<p>ogohlantirish;</p>\r\n\r\n<p>bir martalik mukofotdan mahrum qilish (agar mukofotlashga oid lokal hujjatlarda nazarda tutilgan bo&lsquo;lsa);</p>\r\n\r\n<p>rag&lsquo;batlantirishdan mahrum qilish.</p>\r\n\r\n<p>7.2.&nbsp;Mehnat intizomini buzganligi uchun Universitet xodimga quyidagi intizomiy jazo choralarini qo&lsquo;llashga haqli:</p>\r\n\r\n<p>1) hayfsan;</p>\r\n\r\n<p>o&lsquo;rtacha oylik ish haqining o&lsquo;ttiz foizidan ortiq bo&lsquo;lmagan miqdorda jarima;</p>\r\n\r\n<p>2) mazkur Qoidalarning 2.2.9-bandida ko&lsquo;rsatilgan holatlar bo&lsquo;yicha o&lsquo;rtacha oylik ish haqining ellik foizidan ortiq bo&lsquo;lmagan miqdorda jarima (xodimning ish haqidan jarima ushlab qolish mehnatga oid qonun hujjatlarida nazarda tutilgan talablarga rioya qilingan holda amalga oshiriladi);</p>\r\n\r\n<p>3) mehnat shartnomasini bekor qilish.</p>\r\n\r\n<p>Ushbu bandda nazarda tutilmagan intizomiy jazo choralarini qo&lsquo;llash taqiqlanadi.</p>\r\n\r\n<p>7.3.&nbsp;Intizomiy jazo va ta&rsquo;sir chorasini qo&lsquo;llash Universitet rektorining buyrug&lsquo;i bilan amalga oshiriladi. Aynan bitta mehnat intizomini buzganlik uchun ham intizomiy, ham ta&rsquo;sir chorasi qo&lsquo;llanilishi mumkin emas.</p>\r\n\r\n<p>7.4.&nbsp;Intizomiy jazo chorasi sifatida jarima ilgari mazkur xodimga sodir etilgan nojo&lsquo;ya xatti-harakati uchun hayfsan berilgani yoki berilmaganidan qat&rsquo;i nazar qo&lsquo;llaniladi.</p>\r\n\r\n<p>7.5.&nbsp;Intizomiy jazo qo&lsquo;llanilishidan avval xodimdan yozma ravishda tushuntirish xati talab qilinadi. Xodimning tushuntirish xati berishdan bosh tortishi uning sodir qilgan nojo&lsquo;ya xatti-harakati uchun jazo qo&lsquo;llashga to&lsquo;siq bo&lsquo;la olmaydi. Xodim mehnat intizomini buzganlik xususida tushuntirish xati berishdan bosh tortganligi dalolatnoma bilan rasmiylashtiriladi.</p>\r\n\r\n<p>Intizomiy jazoni qo&lsquo;llashda sodir etilgan nojo&lsquo;ya xatti-harakatning qay darajada og&lsquo;irligi, shu xatti-harakat sodir etilgan vaziyat, xodimning oldingi ishi va xulq-atvori hisobga olinadi.</p>\r\n\r\n<p>7.6.&nbsp;Intizomiy jazo choralari bevosita nojo&lsquo;ya xatti-harakat aniqlangandan keyin, ammo bu xatti-harakat aniqlangandan boshlab uzog&lsquo;i bilan bir oy ichida qo&lsquo;llaniladi. Bir oylik muddatga xodimning kasal yoki ta&rsquo;tilda bo&lsquo;lgan vaqti qo&lsquo;shilmaydi.</p>\r\n\r\n<p>7.7.&nbsp;Nojo&lsquo;ya xatti-harakat sodir etilgan kundan boshlab olti oy o&lsquo;tganidan, moliya-xo&lsquo;jalik faoliyatini taftish etish yoki tekshirish natijasida aniqlanganda esa sodir etilgan kundan boshlab ikki yil o&lsquo;tganidan keyin jazoni qo&lsquo;llab bo&lsquo;lmaydi. Jinoiy ish bo&lsquo;yicha ish yuritilgan davr bu muddatga kirmaydi.</p>\r\n\r\n<p>7.8.&nbsp;Intizomiy jazo berilganligi to&lsquo;g&lsquo;risidagi buyruq xodimga ma&rsquo;lum qilinib, tilxat olinadi. Xodim tilxat berishdan bosh tortgan holda tegishli dalolatnoma bilan rasmiylashtiriladi.</p>\r\n\r\n<p>7.9.&nbsp;Har bir nojo&lsquo;ya xatti-harakat uchun xodimga nisbatan faqat bitta intizomiy jazo qo&lsquo;llanishi mumkin.</p>\r\n\r\n<p>7.10.&nbsp;Intizomiy jazoning amal qilish muddati jazo qo&lsquo;llanilgan kundan boshlab bir yildan oshib ketishi mumkin emas. Agar xodim shu muddat ichida intizomiy jazoga tortilmasa, jazo e&rsquo;lon qilinganidan keyin bir yil o&lsquo;tgach, u intizomiy jazo olmagan deb hisoblanadi. Bunday hollarda intizomiy jazoni olib tashlash to&lsquo;g&lsquo;risida buyruq chiqarilmaydi.</p>\r\n\r\n<p>7.11.&nbsp;Intizomiy jazo rektor tashabbusi bilan, xodimning iltimosiga binoan yoki xodimning bevosita rahbari iltimosiga ko&lsquo;ra bir yil o&lsquo;tmasdan oldin ham olib tashlanishi mumkin. Xodimdan intizomiy jazo muddatidan oldin olib tashlanishi Universitet rektorining buyrug&lsquo;i bilan rasmiylashtiriladi.</p>\r\n\r\n<p>7.12.&nbsp;Intizomiy jazo ustidan xodim mehnatga oid qonun hujjatlarida nazarda tutilgan tartibda shikoyat qilishi mumkin.</p>\r\n\r\n<p>7.13.&nbsp;Xodim tomonidan Universitet va uning mol-mulkiga bevosita to&lsquo;g&lsquo;ridan-to&lsquo;g&lsquo;ri zarar etkazilganda intizomiy jazo qo&lsquo;llanilganligidan qat&rsquo;i nazar, qonunchilikda belgilangan tartibda moddiy javobgarlikka ham tortilishi mumkin.</p>\r\n\r\n<p>7.14.&nbsp;Intizomiy jazo amal qilib turgan muddat mobaynida xodimga nisbatan rag&lsquo;batlantirish choralari qo&lsquo;llanilmaydi.</p>\r\n\r\n<p>7.15.&nbsp;Mazkur Qoidalar, Universitet Odob-axloq kodeksi, Universitetning korrupsiyaga qarshi kurashish dasturi (siyosati), Universitet xodimi, talabalari va doktorantlari tomonidan korrupsiyaviy huquqbuzarliklar sodir etishga og&lsquo;dirish maqsadida murojaat qilish holatlari haqida xabardor qilish to&lsquo;g&lsquo;risidagi nizom, Universitet Ustavi, Universitet Kengashi qarorlari, rektor buyruqlari, lavozim yo&lsquo;riqnomasi, tarkibiy bo&lsquo;linmalar to&lsquo;g&lsquo;risidagi nizomlar va boshqa lokal normativ hujjatlarda belgilangan talablarni buzganligi uchun:</p>\r\n\r\n<p>a) talabalarga:</p>\r\n\r\n<p>Universitetdan chetlashtirish;</p>\r\n\r\n<p>hayfsan;</p>\r\n\r\n<p>uzrsiz sabablarga ko&lsquo;ra darslarni 18 soatdan 36 soatgacha qoldirgan talaba, qoida tariqasida, fakultet dekani tomonidan unga nisbatan intizomiy jazo chorasi qo&lsquo;llanilishi to&lsquo;g&lsquo;risida rasman ogohlantirish;</p>\r\n\r\n<p>uzrli sabablarsiz 36 soatdan 74 soatgacha dars qoldirgan talabaga nisbatan, qoida tariqasida, hayfsan intizomiy jazo chorasi qo&lsquo;llaniladi.</p>\r\n\r\n<p>Intizomiy jazo choralari nojo&lsquo;ya xatti-harakat aniqlangandan keyin bir oy ichida, sodir etilgan kundan boshlab olti oy ichida talaba (doktorant)ning kasal yoki ta&rsquo;tilda bo&lsquo;lgan vaqtini hisobga olmagan holda qo&lsquo;llaniladi, shuningdek, kasal, ta&rsquo;til, akademik ta&rsquo;til yoki homiladorlik va tug&lsquo;ish ta&rsquo;tilida bo&lsquo;lgan davrda Universitetdan chetlashtirishga yo&lsquo;l qo&lsquo;yilmaydi.</p>\r\n\r\n<p>Intizomiy jazoning amal qilish muddati jazo qo&lsquo;llanilgan kundan boshlab bir yildan oshib ketishi mumkin emas. Agar talaba yoki doktorant shu muddat ichida intizomiy jazoga tortilmasa, jazo e&rsquo;lon qilinganidan keyin bir yil o&lsquo;tgach, u intizomiy jazo olmagan deb hisoblanadi. Bunday hollarda intizomiy jazoni olib tashlash to&lsquo;g&lsquo;risida buyruq chiqarilmaydi.</p>\r\n\r\n<p>Talaba yoki doktorantga qo&lsquo;llanilgan intizomiy jazo uning namunaviy xulq-atvori, o&lsquo;qishidagi yuqori ko&lsquo;rsatkichlari, ilmiy-tadqiqot ishlari yoki Universitet ijtimoiy hayotida faol ishtiroki uchun tegishli fakultet dekani bildirgisiga asosan rektorning buyrug&lsquo;i bilan bir yil o&lsquo;tmasdan oldin ham olib tashlanishi mumkin.</p>\r\n\r\n<p>7.16.&nbsp;Universitet talabalari Vazirlar Mahkamasining 2017 yil 20 iyundagi 393-son qarori bilan tasdiqlangan Oliy ta&rsquo;lim muassasalari talabalari o&lsquo;qishini ko&lsquo;chirish, qayta tiklash va o&lsquo;qishdan chetlashtirish tartibi to&lsquo;g&lsquo;risidagi nizom talablari asosida Universitetdan quyidagi hollarda chetlashtirilishi mumkin:</p>\r\n\r\n<p>a) o&lsquo;z xohishiga binoan;</p>\r\n\r\n<p>b) o&lsquo;qishning boshqa ta&rsquo;lim muassasasiga ko&lsquo;chirilishi munosabati bilan;</p>\r\n\r\n<p>v) salomatligi tufayli (tibbiy komissiya ma&rsquo;lumotnomasi asosida);</p>\r\n\r\n<p>g) o&lsquo;quv intizomi va&nbsp;Universitetning Odob-axloq kodeksi hamda ushbu Qoidalarini buzganligi uchun;</p>\r\n\r\n<p>d) bir semestr davomida darslarni uzrli sabablarsiz 74 soatdan ortiq qoldirganligi sababli;</p>\r\n\r\n<p>e) o&lsquo;qish uchun belgilangan to&lsquo;lov o&lsquo;z vaqtida amalga oshirilmaganligi sababli (to&lsquo;lov-kontrakt bo&lsquo;yicha tahsil olayotganlar uchun);</p>\r\n\r\n<p>j) talaba sud tomonidan ozodlikdan mahrum etilganligi munosabati bilan;</p>\r\n\r\n<p>z) sud qaroriga ko&lsquo;ra kirish imtihonlarida belgilangan tartibni buzganligi aniqlanganda (ushbu holatda talabalar safidan chetlashtirilganlar talabalar safiga qayta tiklanmaydi);</p>\r\n\r\n<p>i) vafot etganligi sababli.</p>\r\n\r\n<p>7.17.&nbsp;Universitet tashabbusi bilan talabalarni o&lsquo;qishdan chetlashtirish talabalar kasaba uyushmasining yozma roziligini inobatga olgan holda (kasaba uyushmasi a&rsquo;zosi bo&lsquo;lgan talabalar uchun) amalga oshiriladi. Shuningdek, talaba mazkur Qoidalarning 7.16-bandining &ldquo;g&rdquo; kichik bandiga ko&lsquo;ra chetlashtirilayotgan paytda O&lsquo;zbekiston yoshlar ittifoqi boshlang&lsquo;ich tashkiloti bilan ham kelishilishi mumkin.</p>\r\n\r\n<p>7.18.&nbsp;Akademik qarzdorligi tufayli kursdan qoldirilgan talaba to&lsquo;lov-kontrakt asosida o&lsquo;qishini quyi kursning tegishli o&lsquo;quv semestri boshidan boshlashi mumkin.</p>\r\n\r\n<p>Akademik qarzdorligi tufayli kursdan qoldirilgan talabalar quyi kursdagi tegishli o&lsquo;quv semestridan boshlab faqat o&lsquo;zlashtira olmagan fanlarini (modullarni) takroran o&lsquo;qishi mumkin va ushbu fanlar xajmida kontrakt tulovini amalga oshiradilar.</p>\r\n\r\n<p>7.19. Talaba Universitetdan chetlashtirilganda, unga (ota-onasi yoki huquqiy vasiysiga ularning arizasi bilan) shaxsiy hujjatlari, belgilangan shakldagi akademik ma&rsquo;lumotnoma topshiriladi va ularning nusxasi shaxsiy yig&lsquo;ma jildga tikib qo&lsquo;yiladi.</p>\r\n\r\n<p>7.20. Talabalar safidan chetlashtirilgan fuqarolar o&lsquo;qishini tiklash to&lsquo;g&lsquo;risida ariza berish huquqiga ega.<a name=\"3245845\">&nbsp;O&lsquo;qishini qayta tiklash bo&lsquo;yicha ariza topshirish tiklanadigan semestrda o&lsquo;quv jarayoni boshlanishidan 5 kun oldin muddatidan kechikmay topshirilishi kerak</a></p>\r\n\r\n<p>7.21. Intizomiy jazoga tortilgan talaba o&lsquo;ziga qo&lsquo;llanilgan jazo chorasining qonuniyligi va adolatliligi yuzasidan qonun hujjatlarida belgilangan tartibda shikoyat bilan sud idoralariga murojaat etishi mumkin.</p>\r\n\r\n<p>7.22.&nbsp;Talabaga nisbatan qo&lsquo;llanilgan intizomiy jazo yuzasidan ma&rsquo;lumot uning shaxsiy hujjatlar to&lsquo;plamida saqlanadi.</p>\r\n\r\n<p>7.23.&nbsp;Harbiy xizmatni o&lsquo;tash, salomatligini tiklash, homiladorlik va tug&lsquo;ish, shuningdek, bolalarni parvarish qilish ta&rsquo;tillari davrida talabaga qonun hujjatlarida belgilangan tartibda akademik ta&rsquo;til berilishi mumkin.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>8-bob.&nbsp;Alohida qoidalar</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>8.1.&nbsp;Karantin yoki shu kabi xodim o&lsquo;z mehnat vazifalarini ish joyi (Universitet binosi)da amalga oshirishni imkoni bo&lsquo;lmaganda qonun hujjatlarida nazarda tutilgan tartibda cheklovlar o&lsquo;rnatilgan hollarda ish beruvchi xodimning roziligi bilan uni masofaviy ish usulida, moslashuvchan ish jadvalida yoki uyda ishlash rejimiga o&lsquo;tkazishi mumkin. Bunda:</p>\r\n\r\n<p>xodimning mehnat majburiyatlarini amalga oshirish uchun zarur bo&lsquo;lgan jihozlar va/yoki texnika vositalari zaruriyatga ko&lsquo;ra xodimning yozma talabiga muvofiq ish beruvchi tomonidan ta&rsquo;minlanadi;</p>\r\n\r\n<p>ish beruvchi tomonidan xodimga berilgan jihozlar va texnikalar xodimning aybi bilan buzilganda etkazilgan zarar amaldagi qonun hujjatlariga muvofiq xodim tomonidan ish beruvchiga qoplab beriladi;</p>\r\n\r\n<p>xodim o&lsquo;z mehnat vazifalarini bajarish uchun shaxsiy jihozlar va/yoki texnika vositalaridan, shuningdek, aloqa vositalari, jumladan, internet tarmog&lsquo;idan foydalangan taqdirda bazaviy hisoblash miqdorining bir baravaridan oshmagan miqdorda xarajatlar ish beruvchi tomonidan xodimga qoplab beriladi;</p>\r\n\r\n<p>ishlab chiqarish zaruriyati tug&lsquo;ilganda ish beruvchi xodimni bir kun oldin aloqa vositalari orqali ogohlantirib, uni buyruq asosida doimiy ish joyiga o&lsquo;tkazadi;</p>\r\n\r\n<p>xodim va ish beruvchi o&lsquo;rtasidagi elektron hujjat almashish yo&lsquo;li orqali aloqalar Universitetning ichki lokal hujjatlari hamda boshqa qonun hujjatlarida belgilangan tartibda amalga oshiriladi.</p>\r\n\r\n<p>masofaviy ish usuli (uyda ishlash)ga o&lsquo;tkazilgan xodimning ta&rsquo;tillar jadvaliga muvofiq mehnat ta&rsquo;tili, vaqtincha mehnatga layoqatsizlik bo&lsquo;yicha nafaqa olish hamda qonun hujjatlarida va Universitet jamoa shartnomasida nazarda tutilgan boshqa huquqlari saqlanib qolinadi.</p>\r\n\r\n<p>Masofadan ish deganda xodimning mehnat shartnomasida ko&lsquo;rsatilgan mehnat majburiyatlarini ish beruvchining joylashgan hududidan tashqarida, bevosita yoki bilvosita nazoratida bo&lsquo;lgan doimiy ish joyi, hudud yoki ob&rsquo;ektdan tashqarida bajariladigan ish usuli tushuniladi.</p>\r\n\r\n<p>8.2.&nbsp;Masofaviy ish usulida, moslashuvchan ish jadvalida yoki uyda ishlashga o&lsquo;tish huquqidan birinchi navbatda homilador ayollar, keksalar, imkoniyati cheklangan shaxslar va surunkali kasalliklarga chalingan xodimlar foydalanadi.</p>\r\n\r\n<p>8.3.&nbsp;Xodimni masofaviy ishga vaqtinchalik o&lsquo;tkazishda ish beruvchi tomonidan vaqtinchalik masofaviy ish rejimiga o&lsquo;tkazish haqida muddati ko&lsquo;rsatilgan buyruq chiqariladi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>9-bob. YAkuniy qoidalar</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>9.1.&nbsp;Universitet rektori, rektor maslahatchisi va prorektori tomonidan fuqarolarni qabul qilish tegishli tartibda tasdiqlangan jadval asosida amalga oshiriladi.</p>\r\n\r\n<p>9.2.&nbsp;Mazkur Qoidalar bilan barcha ishga kiruvchilar va talabalar imzo orqali xodimlar bo&lsquo;limi tomonidan tanishtiriladi.</p>\r\n\r\n<p>9.3.&nbsp;Har bir xodim qonun hujjatlari, mazkur Qoidalar, Universitetning boshqa ichki hujjatlari va mehnat shartnomasida belgilangan huquqlarini qonunchilikda nazarda tutilgan vositalar va usullar orqali himoya qilishga, o&lsquo;zining huquqlari buzilgan deb hisoblaganda mustaqil ravishda ish beruvchiga murojaat qilishga haqlidir. Ushbu murojaat belgilangan tartibda ko&lsquo;rib chiqilib, natijasi haqida xodimga ma&rsquo;lum qilinadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>RANCH texnologiya Universitetining kengashi</strong></p>\r\n\r\n<p><strong>tomonidan ma&rsquo;qullangan 14.01.2023 yildagi 3-sonli bayonnoma</strong></p>",
    "descriptions_ru": "<p><strong>ПРАВИЛА внутреннего распорядка Ургенчского технологического университета &laquo;РАНЧ&raquo;</strong></p>\r\n\r\n<p><strong>Правила внутреннего распорядка (правила внутреннего трудового распорядка)</strong></p>\r\n\r\n<p>Настоящие Правила внутреннего распорядка (Правила внутреннего трудового распорядка) (далее - Правила) разработаны с учетом Трудового кодекса Республики Узбекистан, Закона Республики Узбекистан &quot;Об образовании&quot; и других законодательных и подзаконных актов, касающихся высшего образования, и являются локальным нормативным документом, регулирующим отношения, касающиеся труда, учебной, научной деятельности и учебно-воспитательного процесса в высшем образовательном учреждении (далее - Университет).</p>\r\n\r\n<p><strong>Глава 1. Общие правила</strong></p>\r\n\r\n<p><strong>1.1. В настоящих Правилах используются следующие основные понятия:</strong></p>\r\n\r\n<p><strong>работник</strong> - граждане Республики Узбекистан, достигшие установленного возраста и заключившие трудовой договор с Университетом, а также иностранные граждане и лица без гражданства;</p>\r\n\r\n<p><strong>трудовой договор</strong> - соглашение между работником и Университетом о выполнении работы по определенной специальности, квалификации, должности за плату на условиях, установленных соглашением сторон с подчинением внутреннему трудовому распорядку, а также законодательными и иными нормативными актами о труде;</p>\r\n\r\n<p><strong>профессорско-преподавательский состав</strong> - работники, принятые на должности заведующего кафедрой, профессора, доцента, старшего преподавателя, преподавателя, преподавателя-стажера;</p>\r\n\r\n<p><strong>докторант </strong>- лицо, принятое в установленном порядке в Университет в базовую докторантуру или докторантуру;</p>\r\n\r\n<p><strong>независимый исследователь</strong> - лицо, принятое в Университет в качестве независимого исследователя в установленном порядке;</p>\r\n\r\n<p><strong>студент</strong> - лицо, принятое в установленном порядке для обучения в Университете по имеющимся направлениям образования и специальностям по уровням бакалавриата и магистратуры и принимающее науку, воспитание.</p>\r\n\r\n<p>1.2. Настоящие Правила являются основным внутренним нормативным документом, регулирующим вопросы внутреннего трудового распорядка Университета, обязанности Университета, руководства, работника, студента, докторанта, независимых исследователей, а также порядок приема на работу, изменения трудового договора и прекращения трудового договора, организации процесса обучения и воспитания, трудовой и учебной дисциплины, рабочего времени, времени отдыха и его использования, а также поощрения за достижения в работе и учебе, ответственность за нарушение трудовой и учебной дисциплины является основным внутренним нормативным документом, регулирующим порядок на территории и внутри зданий Университета и другие правоотношения, возникающие между работодателем и работником, докторантом, исследователем и студентами.</p>\r\n\r\n<p><strong>Глава 2. Заключение, изменение и прекращение трудового договора</strong></p>\r\n\r\n<p><strong>2.1. Заключение трудового договора</strong></p>\r\n\r\n<p>2.1.1. Трудовые отношения между работником и Университетом устанавливаются на основании заключенного между ними трудового договора.</p>\r\n\r\n<p>2.1.2. При приеме на работу поступающее лицо должно иметь следующие документы:</p>\r\n\r\n<p>паспорт или иной заменяющий его документ с указанием адреса постоянного места жительства или временной прописки;</p>\r\n\r\n<p>трудовая книжка (за исключением лиц, поступающих на работу впервые);</p>\r\n\r\n<p>военный билет или свидетельство о воинском учете, принадлежащие военнообязанным или призывникам;</p>\r\n\r\n<p>диплом о выпуске высшего или среднего специального, профессионального учебного заведения поступающего при поступлении на работу, на выполнение которого в соответствии с законодательством допускаются только лица, имеющие специальную подготовку, свидетельство на право выполнения данной работы (соответствующее свидетельство о нострификации (установлении эквивалентности) диплома, полученного на территории иностранных государств, в установленном законодательством Республики Узбекистан порядке);</p>\r\n\r\n<p>лица, поступающие на работу временно, вместо трудовой книжки предоставляют справку с основного места работы.</p>\r\n\r\n<p>При приеме на работу запрещается требовать от поступающего документы, не предусмотренные законодательством.</p>\r\n\r\n<p>В приеме на работу в случае недействительности паспорта или иного документа, удостоверяющего личность поступающего на работу, может быть отказано.</p>\r\n\r\n<p>В целях ведения учета кадров и формирования базы данных о них принятым на работу сотрудником в Отдел кадров представляются следующие документы:</p>\r\n\r\n<p>опросник;</p>\r\n\r\n<p>биография;</p>\r\n\r\n<p>справка (объективка);</p>\r\n\r\n<p>4 фото (включая электронный вариант)</p>\r\n\r\n<p>2.1.3. После проверки полноты представленных документов, указанных в абзацах втором-шестом пункта 4 настоящих Правил, поступающим на работу лицом составляется заявление и регистрируется в канцелярии Университета. В заявлении должно быть записано полное, без сокращения, имя, фамилия, отчество поступающего на работу, а должность, на которую он поступает, должна соответствовать должности, определенной в штатном расписании.</p>\r\n\r\n<p>2.1.4. Между работником, принимаемым на работу, и работодателем заключается трудовой договор о:</p>\r\n\r\n<p>должность и место работы, на которое принимается работник;</p>\r\n\r\n<p>срок трудового договора;</p>\r\n\r\n<p>день начала работы;</p>\r\n\r\n<p>трудовые права и обязанности сторон;</p>\r\n\r\n<p>порядок рабочего времени и предоставление трудового отпуска;</p>\r\n\r\n<p>порядок оплаты труда;</p>\r\n\r\n<p>иные обстоятельства, предусмотренные трудовым законодательством.</p>\r\n\r\n<p>В случаях, когда в трудовом договоре не указан срок его действия, данный договор считается заключенным на неопределенный срок.</p>\r\n\r\n<p>Заключение срочного трудового договора осуществляется в соответствии с законодательными и иными нормативными актами о труде.</p>",
    "descriptions_en": "<p><strong>Internal Regulations of Urgench RANCH University of Technology</strong></p>\r\n\r\n<p>These internal regulations (referred to hereinafter as &quot;Regulations&quot;) have been developed in accordance with the Labor Code of the Republic of Uzbekistan, the &quot;Education&quot; Law, and other legislation related to higher education. They serve as a local normative document regulating labor, educational, scientific activities, and the educational and upbringing process within the higher educational institution (hereinafter referred to as &quot;University&quot;).</p>\r\n\r\n<p><strong>Chapter 1. General rules</strong></p>\r\n\r\n<p><strong>1.1. These Rules use the following basic concepts:</strong></p>\r\n\r\n<p><strong>employee</strong> &ndash; a citizen of the Republic of Uzbekistan who has reached the required age and entered into an employment contract with the University, as well as foreign citizens and stateless persons;</p>\r\n\r\n<p><strong>employment contract</strong> &ndash; an agreement between the employee and the University to perform work in a specific specialty, qualification, or position, under the internal labor regulations, based on mutual consent, and in accordance with labor laws and other regulatory documents;</p>\r\n\r\n<p><strong>professors and teachers</strong> &ndash; employees appointed to positions such as department head, professor, associate professor, senior lecturer, lecturer, or lecturer-intern;</p>\r\n\r\n<p><strong>doctoral student</strong>&nbsp;&ndash; an individual admitted to the University for basic or full-time doctoral studies, in accordance with the prescribed procedure;</p>\r\n\r\n<p><strong>independent researcher</strong> &ndash; an individual admitted to the University for independent research work according to the established procedure;</p>\r\n\r\n<p><strong>student</strong> &ndash; an individual admitted to the University to pursue education in undergraduate or graduate programs, as well as in specialized fields, and who is guided by academic staff for scientific and educational development.</p>\r\n\r\n<p>1.2.These Rules define the University&#39;s internal labor procedures, the duties of the University, its administration, employees, students, doctoral students, and independent researchers. They also establish the procedures for hiring, changing, and canceling employment contracts, organizing the education and training process, labor and academic discipline, working hours, rest periods, and their use. Additionally, they cover incentives for achievements in work and study, responsibilities for violations of labor and academic discipline, the maintenance of order within the University&#39;s territory and buildings, and other legal relations involving employees, doctoral students, independent researchers, and students. These Rules serve as the primary internal regulatory document governing these matters.</p>\r\n\r\n<p><strong>Chapter 2. Conclusion, amendment and cancellation of the employment contract</strong></p>\r\n\r\n<p><strong>2.1. Conclusion of an employment contract</strong></p>\r\n\r\n<p>2.1.1.The labor relations between the employee and the University are established based on the employment contract concluded between them.</p>\r\n\r\n<p>2.1.2. At the time of employment, the person entering the job has the following documents:</p>\r\n\r\n<p>passport or other document that replaces it with the address of permanent residence or temporary registration;</p>\r\n\r\n<p>employment record (except for persons entering employment for the first time);</p>\r\n\r\n<p>a military ticket or a certificate of being in the military account for conscripts or conscripts;</p>\r\n\r\n<p>at the time of employment, for tasks that can only be performed by individuals with specialized training in accordance with the law, the employee must present their diploma of graduation from a higher or secondary specialized vocational school, along with a certificate granting the right to perform this job. This includes a relevant certificate confirming that the diploma obtained in a foreign country has been nostrified (recorded as equivalent) in accordance with the procedure established by the legislation of the Republic of Uzbekistan.</p>\r\n\r\n<p>Instead of a work record book, individuals entering work on a temporary basis must submit a certificate from their primary place of employment.</p>\r\n\r\n<p>It is prohibited to request documents not specified in the legislation from an individual entering a job during the hiring process.</p>\r\n\r\n<p>If an applicant&#39;s passport or other identity document is invalid, they may be refused employment.</p>\r\n\r\n<p>In order to maintain personnel records and create a database, the following documents must be submitted to the Personnel Department by the employed individual:</p>\r\n\r\n<p>Application;</p>\r\n\r\n<p>biography;</p>\r\n\r\n<p>CV;</p>\r\n\r\n<p>4 photos&nbsp; (electronic version also required)</p>\r\n\r\n<p>2.1.3. After checking the completeness of the documents specified in the second-sixth paragraphs of Clause 4 of these Rules, the applicant will write an application and register it in the University office. In the application, the name, surname, and patronymic of the applicant must be written in full, without abbreviations, and the position he is applying for must correspond to the position specified in the staff list.</p>\r\n\r\n<p>2.1.4. An employment contract is concluded between the employee and the employer regarding the following:</p>\r\n\r\n<p>position and workplace where the employee is employed;</p>\r\n\r\n<p>employment contract</p>"
  }
];

export const axloq_qoidasi = [
  {
    "desc_uz": "<h4>URGANCH RANCH TEXNOLOGIYA UNIVERSITETINING ODOB-AXLOQ KODEKSI</h4>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Mazkur odob-axloq kodeksi Univtrsitet Kengashining 2023-yil 14 yanvar kungi&nbsp; majlisida muhokama qilinib, tasdiqlangan</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>1-bob.&nbsp;Umumiy qoidalar</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>1-modda.&nbsp;Ushbu kodeks bilan tartibga solinadigan munosabatlar</strong></p>\r\n\r\n<p>Ushbu Kodeks O&lsquo;zbekiston Respublikasi &ldquo;Ta&rsquo;lim to&lsquo;g&lsquo;risida&rdquo;gi qonuni, boshqa qonun va qonunosti hujjatlarga&nbsp;muvofiq ishlab chiqilgan bo&lsquo;lib,&nbsp;<strong>Urganch Ranch Texnologiya Universiteti</strong>&nbsp;(keyingi o&lsquo;rinlarda &ndash;&nbsp;Universitet) pedagog va boshqa xodimlari, talabalari, doktorantlari (keyingi o&lsquo;rinlarda &ndash; xodim, talaba va doktorant) kasbiy odob-axloqining tamoyillari, normalari, ta&rsquo;lim jarayoni va xizmatdagi xulq-atvorining asosiy qoidalari bilan bog&lsquo;liq munosabatlarni tartibga soladi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>2-modda.&nbsp;Odob-axloq kodeksining maqsad va vazifalari</strong></p>\r\n\r\n<p>Odob-axloq kodeksining maqsadlari:</p>\r\n\r\n<p>xodim, talaba va doktorantlarda umumiy madaniyatni rivojlantirish;</p>\r\n\r\n<p>Universitet xodimi, talabasi va doktorantlarining zamonaviy imijini shakllantirish;</p>\r\n\r\n<p>xodim, talaba va doktorantlarni&nbsp;Universitet&nbsp;va uning qadriyatlariga hurmat ruhida tarbiyalash;</p>\r\n\r\n<p>Universitet odob-axloqi tushunchasini takomillashtirish va&nbsp;Universitetda tashqi ko&lsquo;rinish va xulq-atvorga bo&lsquo;lgan talablarga oid yagona yondashuvni ishlab chiqishdan iboratdir.</p>\r\n\r\n<p>Odob-axloq kodeksining vazifalari quyidagilardan iborat:</p>\r\n\r\n<p>huquqbuzarlik va jinoyatchilikning oldini olish, xodim, talaba va doktorantlar orasida odob-axloq qoidalarini buzish bilan bog&lsquo;liq bo&lsquo;lgan nomaqbul hatti-harakat, jumladan, zo&lsquo;ravonlik, shafqatsizlik va hayosizlikni targ&lsquo;ib va tashviq qilish, shuningdek, turli salbiy illatlar va milliy mentalitetimizga yot bo&lsquo;lgan g&lsquo;oya va qarashlar, ekstremizm, separatizm, fundamentalizm va &ldquo;ommaviy madaniyat&rdquo;ning ta&rsquo;siri hamda xurujlaridan himoya qilish;</p>\r\n\r\n<p>mazkur nomaqbul xatti-harakatlar sodir etilishining sabab va shart-sharoitlarini aniqlash va ularni bartaraf etish;</p>\r\n\r\n<p>xodim, talaba va doktorantlarni yuksak huquqiy ong, O&lsquo;zbekiston Respublikasining Konstitutsiyasi, qonunlari va boshqa normativ-huquqiy hujjatlariga qat&rsquo;iy rioya qilish ruhida tarbiyalash;</p>\r\n\r\n<p>xodim, talaba va doktorantlarda fuqarolarning huquqlari, erkinliklari va manfaatlarini doimo hurmat qilish va himoya qilish ko&lsquo;nikmasini shakllantirish va yuksaltirish;</p>\r\n\r\n<p>xodim, talaba va doktorantlarda vatanparvarlik, yuksak ma&rsquo;naviy-axloqiy fazilatlarni shakllantirish va ularni milliy qadriyatlarimizni hurmat qilish, xotin-qizlar sha&rsquo;ni va qadr-qimmatini hurmat qilish, ularga nisbatan nomaqbul xatti-harakatlarga yo&lsquo;l qo&lsquo;ymaslik ruhida tarbiyalash;</p>\r\n\r\n<p>Universitetda sog&lsquo;lom ijtimoiy-psixologik muhitni shakllantirish va rivojlantirish;</p>\r\n\r\n<p>Universitet xodimi, talabasi va doktorantlarida tashqi ko&lsquo;rinishga oid madaniyatni shakllantirish uchun sharoitlar yaratish;</p>\r\n\r\n<p>Universitetning davlat va jamiyat hayotidagi hamda ta&rsquo;lim tizimidagi nufuzi, obro&lsquo;-e&rsquo;tiborini asrab-avaylash va yanada oshirish.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>3-modda. Kodeksning amal qilish doirasi</strong></p>\r\n\r\n<p>Ushbu Kodeks&nbsp;Universitetning barcha xodim, talaba va doktorantlariga nisbatan tatbiq etiladi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>2-bob.&nbsp;</strong><strong>Kodeksning prinsiplari</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>4-modda. Universitet xodimi</strong><strong>,</strong><strong>&nbsp;</strong><strong>talabasi va doktorantlari xulq-atvorining asosiy prinsiplari</strong></p>\r\n\r\n<p>Mazkur Kodeks qonuniylik, fuqarolarning huquqlari, erkinliklari va qonuniy manfaatlarining ustuvorligi, vatanparvarlik, xizmat va o&lsquo;qish burchiga sodiqlik, adolat, halollik va xolislik, samaradorlik va tejamkorlik prinsiplariga asoslanadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>5-modda. Qonuniylik prinsipi</strong></p>\r\n\r\n<p>Universitet xodimi, talabasi va doktorantlari O&lsquo;zbekiston Respublikasi qonunchiligiga so&lsquo;zsiz rioya qiladilar hamda o&lsquo;z xizmat va o&lsquo;qish majburiyatlarini lavozim yo&lsquo;riqnomalari, mehnat shartnomalari, ushbu Kodeks qoidalari,&nbsp;Universitet&nbsp;Ichki tartib qoidalari hamda ta&rsquo;limga oid boshqa me&rsquo;yoriy hujjatlarga muvofiq bajaradilar.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>6-modda. Fuqarolarning huquqlari, erkinliklari va qonuniy<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; manfaatlarining ustuvorligi prinsipi</strong></p>\r\n\r\n<p>Fuqarolarning huquqlari, erkinliklari va qonuniy manfaatlari&nbsp;Universitetning oliy qadriyati bo&lsquo;lib hisoblanadi. Universitet xodimi, talabasi va doktorantlari fuqarolarning huquqlari, erkinliklari va qonuniy manfaatlari buzilishiga yo&lsquo;l qo&lsquo;ymaydilar va bunday buzilishlar ro&lsquo;y bergan hollarda ularni tiklashga ko&lsquo;maklashadilar.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>7-modda. Vatanparvarlik, xizmat va o&lsquo;qish burchiga sodiqlik<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; prinsipi</strong></p>\r\n\r\n<p>Universitet xodimi, talabasi va doktorantlari o&lsquo;z o&lsquo;qish va xizmat faoliyatlarini ma&rsquo;naviy-axloqiy qadriyatlar, Vatanga sadoqat, xizmat va o&lsquo;qish burchiga sodiqlik asosida jamiyatning Universitetga bo&lsquo;lgan talabi va ishonchini ifodalagan holda amalga oshiradilar. Xodim, talaba va doktorantlar o&lsquo;z o&lsquo;qish va xizmat burchlarini o&lsquo;zaro xayrixohlik, o&lsquo;z manfaatlari va mafkuraviy qarashlaridan qat&rsquo;iy nazar lozim darajada bajaradilar.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>8-modda. Adolat, halollik va xolislik prinsipi</strong></p>\r\n\r\n<p>Universitet xodimi, talabasi va doktorantlari o&lsquo;z xizmat va o&lsquo;qish faoliyatlarini amalga oshirishda adolatli, halol va xolis bo&lsquo;lishlari hamda Universitetga, unga tegishli bo&lsquo;lgan saytlar va ijtimoiy tarmoqlarga murojaat qilgan barcha yuridik va jismoniy shaxslarga nisbatan ushbu prinsip talablari asosida munosabatda bo&lsquo;lishlari shart.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>9-modda. Samaradorlik va tejamkorlik prinsipi</strong></p>\r\n\r\n<p>Universitet xodimi, talabasi va doktorantlari o&lsquo;z faoliyati samaradorligini innovatsion texnologiyalarni tatbiq etish va boshqa yo&lsquo;llar bilan doimiy ravishda oshirib boradilar.</p>\r\n\r\n<p>Universitet xodimi, talabasi va doktorantlari o&lsquo;z navbatida Universitetning mulkiga, o&lsquo;zining va boshqa shaxslarning vaqtiga mas&rsquo;uliyat va ehtiyotkorlik bilan yondashadilar.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>3-bob. Korrupsiyaga qarshi kurashish</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>10-modda. Korrupsiyaning har qanday shakl va ko&lsquo;rinishini qabul<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; qilmaslik</strong></p>\r\n\r\n<p>Universitet xodimi, talabasi va doktorantlari korrupsiyaning har qanday shakli va ko&lsquo;rinishini qabul qilmaydilar va uning biror-bir tarzda namoyon bo&lsquo;lishiga qarshi hamjihatlikda qonuniy choralarni ko&lsquo;radilar.</p>\r\n\r\n<p>Xodim, talaba va doktorantlar korrupsiyaga qarshi kurashishlari va uning profilaktikasiga faol ko&lsquo;maklashishlari, shuningdek, 03.01.2017 yildagi 419-sonli O&lsquo;zbekiston Respublikasining&nbsp;&ldquo;Korrupsiyaga qarshi kurashish to&lsquo;g&lsquo;risida&rdquo;gi&nbsp;Qonuni talablarini so&lsquo;zsiz bajarishlari, o&lsquo;z faoliyatlarini oshkora va adolatli amalga oshirishlari, yuqori axloqiy qadriyatlar va prinsiplarga sodiq qolgan holda qonun ustuvorligiga qat&rsquo;iy rioya etishlari shart.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>4-bob.&nbsp;Xodim</strong><strong>,</strong><strong>&nbsp;</strong><strong>talaba va doktorantlar yurish-turish va rasmiy muloqotiga oid talablar</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>11-modda.&nbsp;Universitetda kiyinish va tashqi ko&lsquo;rinishga oid qoidalar</strong></p>\r\n\r\n<p>Universitet xodimi, talabasi va doktorantlari o&lsquo;z o&lsquo;qish va kasbiga mos bo&lsquo;lgan zamonaviy, diqqatni tortmaydigan kiyimda bo&lsquo;lishlari lozim. Shuningdek, o&lsquo;zlari bilan zaruriy o&lsquo;quv vositalarini olib kelishlari shart.</p>\r\n\r\n<p>Talabalarning Universitetga kelishi ruxsat etilgan formasiga turli din va konfessiyalar hamda submadaniyatlarga mansublikni aks ettiruvchi elementlarni (hijob, kipa, kashaya, xoch va boshqalar) qo&lsquo;shishga yo&lsquo;l qo&lsquo;yilmaydi.</p>\r\n\r\n<p>Xodim, talaba va doktorantlarning auditoriya va xizmat xonalarida ustki kiyim (plash, palto<em>,</em>&nbsp;kurtka kabilar)da yurishlari taqiqlanadi.</p>\r\n\r\n<p>Xodimlar, talabalar va doktorantlarning tashqi qiyofasi va kiyimlari ozoda, pokiza bo&lsquo;lishi lozim.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>12-modda.&nbsp;Majlis va yig&lsquo;inlarda ishtirok etish</strong></p>\r\n\r\n<p>Universitet xodimi talabasi va doktorantlari turli tadbirlar (majlislar, tantanali yig&lsquo;ilishlar, uchrashuvlar, bayramlar)dagi ishtiroki jarayonida so&lsquo;zga chiquvchilarga nisbatan hurmat bilan munosabatda bo&lsquo;lishlari, tadbir davomida tinchlik va osoyishtalikni saqlashlari shart bo&lsquo;lib, raislik qiluvchi va moderatorning ruxsatisiz luqma tashlash va so&lsquo;zga chiqish mumkin emas. Zarurat tug&lsquo;ilganda nutqlar o&lsquo;rtasida majlislar zalidan chiqib-kirish mumkin.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>13-modda.&nbsp;Binolarda yurish-turish qoidalariga amal qilish</strong></p>\r\n\r\n<p>Binolarga kirish va chiqish joylarida, shuningdek, yo&lsquo;laklarda talabalar xodimlarni, erkaklar ayollarni, yoshlar esa kattalarni o&lsquo;zlaridan oldin o&lsquo;tkazib yuborishlari lozim.</p>\r\n\r\n<p>Binoga kirayotgan har bir shaxs binolarga kirib-chiqishni nazorat qilish uchun tayinlangan mas&rsquo;ul shaxs yoki navbatchiga o&lsquo;z shaxsini tasdiqlovchi hujjatni (xizmat yoki talabalik guvohnomasi, pasport va h.k.) ochiq holda ko&lsquo;rsatishlari yoki maxsus berilgan ID-karta orqali turniketlardan o&lsquo;tishlari shart.</p>\r\n\r\n<p>Xodim, talaba va doktorantlar Universitet hududida yo&lsquo;lning o&lsquo;ng tomonidan yurishlari, shuningdek, yo&lsquo;lak va xollarda mobil aloqa vositalari orqali baland ovozda gaplashmasliklari kerak. Bir-birlariga duch kelganda salomlashishlari, bunda: talabalar xodimlarga, yoshlar kattalarga birinchi bo&lsquo;lib salom berishlari tavsiya etiladi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>14-modda.&nbsp;</strong><strong>X</strong><strong>odim</strong><strong>,</strong><strong>&nbsp;</strong><strong>talaba va doktorantlarning rasmiy muloqot<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; me&rsquo;yorlari</strong></p>\r\n\r\n<p>Universitet xodimi, talabasi va doktorantlari tashkilot va muassasalar, ommaviy axborot vositalari hamda fuqarolar bilan o&lsquo;zaro munosabatga kirishganda quyidagi rasmiy muloqot me&rsquo;yor va qoidalariga amal qilishlari kerak:</p>\r\n\r\n<p>o&lsquo;z harakatlarini Universitet manfaatlarini ko&lsquo;zlab amalga oshirish, uning imijini saqlash va oshirish, Universitet uning xodimlari, talabalari va doktorantlari nomi va manfaatlariga ziyon etkazadigan harakatlarni amalga oshirmaslik, shuningdek, ular bilan muloqot qilganda hamda ijtimoiy tarmoqlardagi yozishmalarida o&lsquo;zlarining namunali xulq-atvori bilan Universitet haqida yuksak ijobiy taassurot uyg&lsquo;otish;</p>\r\n\r\n<p>xotin-qizlar bilan munosabatlar amaldagi qonunchilik hujjatlari talablari, milliy an&rsquo;analar va o&lsquo;zaro hurmat tamoyillariga asoslanishi shart;</p>\r\n\r\n<p>Universitet, uning xodimi, talabasi va doktorantlari haqida haqiqatga to&lsquo;g&lsquo;ri kelmaydigan yoki noto&lsquo;g&lsquo;ri talqin qilingan, noto&lsquo;g&lsquo;ri talqin qilish uchun imkon beradigan ma&rsquo;lumotlarni tarqatmaslik, bunday ma&rsquo;lumotlar tarqalishiga yo&lsquo;l qo&lsquo;ymaslik, shuningdek, jamoat oldida va ijtimoiy tarmoqlarda bu mavzuda chiqishlar qilmaslik;</p>\r\n\r\n<p>xodim, talaba va doktorantlarning roziligisiz ularning shaxsiy hayotiga oid ma&rsquo;lumotlarni oshkor qilmaslik;</p>\r\n\r\n<p>xodim, talaba va doktorantlar haqida ularning kasbiy va o&lsquo;quv faoliyatiga oid bo&lsquo;lmagan ma&rsquo;lumotlarni aniqlashtirmaslik;</p>\r\n\r\n<p>xizmat axborotlarini taqdim etish qoidalariga amal qilish;</p>\r\n\r\n<p>so&lsquo;ralgan axborotni etarlilik (haddan tashqari qisqa shu bilan birga o&lsquo;ta keragidan ortiq) va ishonchlilik (qayta tekshirishni talab qilmaydigan) talablariga muvofiq holda taqdim etish;</p>\r\n\r\n<p>o&lsquo;z xizmat vazifalarini bajarish jarayonida olingan ma&rsquo;lumotlardan maqsadga muvofiq bo&lsquo;lmagan tarzda foydalanmaslik, shuningdek, ularni Universitet rahbariyati ruxsatisiz tarqatmaslik;</p>\r\n\r\n<p>xodim, talaba va doktorantlarning ta&rsquo;lim jarayonidagi faoliyati va kasbiy harakatlarini asossiz tanqid qilmaslik, jamoat oldida chiqishlar, shunindek, ommaviy axborot vositalari va turli xil ijtimoiy tarmoqlarda davlat hokimiyati va boshqaruvi organlari va Universitet faoliyati, uning xodimlari harakatlarini haqiqatga to&lsquo;g&lsquo;ri kelmaydigan, asossiz va aniq dalillarga asoslanmagan holda muhokama qilmaslik va ular haqida baho berib, fikr-mulohazalar bildirmaslik.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>15-modda.&nbsp;Ish va o&lsquo;qish vaqtiga rioya qilish</strong></p>\r\n\r\n<p>Xodim, talaba va doktorantlar dars mashg&lsquo;ulotlari va ishga o&lsquo;z vaqtida kelishlari, mehnat hamda o&lsquo;qish intizomiga rioya qilishlari shart.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>16-modda.&nbsp;Universitetda g&lsquo;ayriaxloqiy va nojo&lsquo;ya xatti-harakatlarni sodir etishga yo&lsquo;l qo&lsquo;yilmasligi</strong></p>\r\n\r\n<p>Talaba va doktorantning o&lsquo;qishiga, xodimning esa Universitetda mehnat faoliyatini yuritishiga to&lsquo;sqinlik qiladigan quyidagi g&lsquo;ayriaxloqiy va nojo&lsquo;ya xatti-harakatlarni sodir etishi qat&rsquo;iyan taqiqlanadi:</p>\r\n\r\n<p>har qanday huquqbuzarlik yoki jinoyat sodir etish, jumladan, tuhmat qilish, haqoratlash;</p>\r\n\r\n<p>giyohvand moddalar, psixotrop vositalar va ularning analoglari, alkogol va tamaki mahsulotlarini iste&rsquo;mol qilish va tarqatish;</p>\r\n\r\n<p>tinchlik yoki osoyishtalikka qarshi tajovuz qilish, janjallashish, qimor va tavakkalchilikka asoslangan boshqa o&lsquo;yinlar o&lsquo;ynash;</p>\r\n\r\n<p>Universitetga moddiy va uning ishchanlik obro&lsquo;siga salbiy ta&rsquo;sir etuvchi ma&rsquo;naviy zarar etkazish;</p>\r\n\r\n<p>xodim,&nbsp;talaba va doktorantlarga jismoniy, ma&rsquo;naviy yoki moddiy zarar etkazish;</p>\r\n\r\n<p>Universitet<em>&nbsp;atrof-muhitini har qanday ko&lsquo;rinishda ifloslantirish</em>;</p>\r\n\r\n<p>Universitet binolari va hovlisida, shuningdek, Universitet binolariga tutashgan hududda spirtli ichimliklar ichish va tamaki yoxud boshqa turdagi mahsulotlarni chekish hamda mast holda bo&lsquo;lish, tashqi ko&lsquo;rinishga va ushbu Kodeksda belgilangan qoidalarga zid ravishda soch-soqoli o&lsquo;sgan, to&lsquo;zg&lsquo;igan va kiyinish talablariga rioya qilmagan holda kelish;</p>\r\n\r\n<p>Universitetga tegishli kompyuterlarda Universitetga tegishli bo&lsquo;lmagan ma&rsquo;lumotlarni, shuningdek, turli kinofilmlar, noqonuniy ma&rsquo;lumotlar, behayo surat va filmlar, milliy, irqiy, etnik, diniy adovatni targ&lsquo;ib qiluvchi, ekstremistik, separatistik va fundamentalistik kayfiyatdagi har qanday materiallarni tayyorlash, ko&lsquo;rish, saqlash, tarqatish va ularga da&rsquo;vat etish;</p>\r\n\r\n<p>o&lsquo;quv mashg&lsquo;ulotlari va ishga hamda xodim va talabalarning osoyishtaligiga xalaqit beradigan xatti-harakatlar sodir etish (radiouzatgich, televizor, multimedia va ovoz chiqaruvchi moslamalardan maqsadsiz foydalanish);</p>\r\n\r\n<p>umumbashariy va milliy qadriyatlarga xos bo&lsquo;lmagan yoki Universitet, uning xodimlari nufuziga putur etkazadigan materiallarni Internet tarmog&lsquo;i va boshqa ijtimoiy tarmoqlarga joylashtirish yoki ulardan turli nomuvofiq maqsadlarda foydalanish.</p>\r\n\r\n<p>Xodimlar, talabalar va doktorantlar tomonidan Universitetning ishchanlik obro&lsquo;si, qadr-qimmati va nufuzini tushiradigan, ta&rsquo;lim jarayonining ma&rsquo;naviy buzilishiga olib keladigan agressiya, odamlarning sha&rsquo;ni va qadr-qimmatini kamsitadigan, zo&lsquo;rlash va vahshiylik, vandalizm, millatlararo nizo qo&lsquo;zg&lsquo;atadigan, diniy yo&lsquo;nalishdagi, terrorizm, ekstremizm, va fundamentalizm, shuningdek, behayo va ishqiy sahnalarni namoyon qiladigan fotosuratlar, video va audioyozuvlardan foydalanish va ularning tarqatilishiga yo&lsquo;l qo&lsquo;yilmaydi.</p>\r\n\r\n<p>SHuningdek, davlat hokimiyati va boshqaruvi organlari va Universitet faoliyati, uning xodimlari hamda talabalari sha&rsquo;ni va qadr qimmati hamda ishchanlik obro&lsquo;siga salbiy ta&rsquo;sir qiluvchi haqiqatga to&lsquo;g&lsquo;ri kelmaydigan, asossiz va tekshirilgan dalillarga asoslanmagan turli xil ko&lsquo;rinishdagi ma&rsquo;lumot, fikr, mulohaza va munosabatlarni Internet, ijtimoiy tarmoqlar, shuningdek, boshqa ommaviy axborot manbalarida, tarqatuvchilarda, tashuvchilarda paydo bo&lsquo;lishi (oshkor etilishi) hamda shunday ma&rsquo;lumotlarga ijobiy munosabat bildirish (&ldquo;layk&rdquo; bosish, repost qilish) mazkur talaba va doktorantning o&lsquo;qishiga, xodimning esa Universitetda mehnat faoliyatini yuritishiga to&lsquo;sqinlik qiladigan g&lsquo;ayriaxloqiy va nojo&lsquo;ya xatti-harakat hisoblanadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>5-bob. Universitet rahbariyatining odob-axloqqa oid majburiyatlari va kasbiy faoliyatda manfaatlar to&lsquo;qnashuviga yo&lsquo;l qo&lsquo;ymaslikka oid tartiblar</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>17-modda.&nbsp;Rahbarning majburiyatlari</strong></p>\r\n\r\n<p>Rahbariyat hamda tarkibiy bo&lsquo;linma rahbarlari (keyingi o&lsquo;rinlarda &ndash; rahbar) o&lsquo;ziga bo&lsquo;ysunuvchi xodimlarga nisbatan yuqori professionallik, xolislik, soflik va adolatda o&lsquo;rnak bo&lsquo;lishi, Universitet yoxud uning tarkibiy bo&lsquo;linmasida ijobiy, ma&rsquo;naviy-psixologik muhit shakllanishiga ko&lsquo;maklashishi lozim. Rahbar bo&lsquo;ysunuvchi xodimlardan ularning xizmat vazifalari doirasidan chiquvchi topshiriqlarni bajarishini talab qilmasligi, shuningdek, qonunga xilof xatti-harakatlarni sodir etishga undamasligi kerak.</p>\r\n\r\n<p>Rahbar o&lsquo;z faoliyatida:</p>\r\n\r\n<p>kadrlarni qarindoshlik, hamshaharlik yoki shaxsiy sadoqat belgilari bo&lsquo;yicha tanlash va joy-joyiga qo&lsquo;yish va mehnat munosabatlarida kamsitish holatlariga yo&lsquo;l qo&lsquo;ymasligi;</p>\r\n\r\n<p>guruhbozlik, mahalliychilik, favoritizmga, shuningdek, o&lsquo;z xizmat vazifalarini bajarish jarayonida boshqa salbiy omillarning kelib chiqishiga yo&lsquo;l qo&lsquo;ymasligi;</p>\r\n\r\n<p>qo&lsquo;pollik qilmasligi, odamlarning sha&rsquo;ni va qadr-qimmatini kamsitmasligi, ularga psixologik va jismoniy ta&rsquo;sir ko&lsquo;rsatmasligi;</p>\r\n\r\n<p>manfaatlar to&lsquo;qnashuvining oldini olish va ularni tartibga solish yuzasidan o&lsquo;z vaqtida chora-tadbirlar ko&lsquo;rishi;</p>\r\n\r\n<p>korrupsiyaning oldini olish choralarini ko&lsquo;rishi;</p>\r\n\r\n<p>xodimlarning kasbiy va intellektual jihatdan rivojlanishlari uchun qulay ish joyi, zamonaviy kompyuterlar, internet tarmog&lsquo;i, kutubxona fondi va axborot resurslaridan erkin foydalanishlari, hordiq chiqarishlari, dam olishlari, jismonan chiniqishlari uchun barcha sharoitlarni ichki imkoniyatlardan kelib chiqib yaratib berishi;</p>\r\n\r\n<p>xodimlar faoliyatini samarali tashkil etib, o&lsquo;ziga ishonib topshirilgan mulkka va moliyaviy mablag&lsquo;larga ehtiyotkorlik va tejamkorlik bilan munosabatda bo&lsquo;lishi shart.</p>\r\n\r\n<p>Rahbar qo&lsquo;l ostidagi xodimlarning mehnat intizomiga rioya qilishlarini talab qilishi va uni ta&rsquo;minlashga mas&rsquo;uldir.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>6-bob.&nbsp;</strong><strong>X</strong><strong>odim</strong><strong>,</strong><strong>&nbsp;</strong><strong>talaba va doktorantlarning o&lsquo;zaro</strong></p>\r\n\r\n<p><strong>munosabatlariga oid talablar</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>18-modda.&nbsp;</strong><strong>X</strong><strong>odim</strong><strong>,</strong><strong>&nbsp;</strong><strong>talaba va doktorantlarning o&lsquo;zaro munosabatlari</strong></p>\r\n\r\n<p>Xodim, talaba<strong>&nbsp;</strong>va doktorantlarning o&lsquo;zaro munosabatlari milliy qadriyat va an&rsquo;analar, yagona jamoaviy muhit, o&lsquo;zaro hurmat va e&rsquo;tibor, do&lsquo;stlik, hamjihatlik, halollik va adolat tamoyillariga asoslanishi lozim.</p>\r\n\r\n<p>Xodim, talaba<strong>&nbsp;</strong>va doktorantlarning o&lsquo;zaro munosabatlarida inson qadr-qimmatiga hurmatsizlik, shaxsiyatni kamsitish, o&lsquo;zganing intellektual mulkini o&lsquo;zlashtirib olish, qo&lsquo;pollik, behayo so&lsquo;zlar ishlatish, mushtlashish qat&rsquo;iyan man etiladi.</p>\r\n\r\n<p>Pedagog xodimlar tomonidan talabalarga nisbatan o&lsquo;quv va tarbiya jarayonidagi yuqori talabchanlik ularning shaxsini hurmat qilish bilan birgalikda amalga oshirilishi kerak.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>19-modda.&nbsp;Pedagog xodim va talabalarning auditoriyadagi va undan<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; tashqaridagi o&lsquo;zaro munosabatlari</strong></p>\r\n\r\n<p>Pedagog xodim auditoriyaga kirganida, barcha talabalar o&lsquo;rinlaridan turib hurmatlarini bildirgan holda kutib olishlari, so&lsquo;ngra pedagog xodim salomlashib, o&lsquo;tirishga ruxsat bergach, o&lsquo;z joylarini egallashlari kerak. Pedagog xodim darsini tugatib, auditoriyadan chiqib ketayotganda ham talabalar o&lsquo;rinlaridan turib, kuzatib qo&lsquo;yishlari lozim.</p>\r\n\r\n<p>Pedagog xodimlar o&lsquo;quv jarayoni va boshqa holatlarda ham talabalarning shaxsini hurmat qilishi, ular bilan munosabatda ochiqlik va&nbsp; xayrixohlik tamoyillariga amal qilish, talabalarga ta&rsquo;lim berish jarayonida o&lsquo;z vazifalarini beg&lsquo;araz amalga oshirishi, talabaga munosabatda ularni kamsitish, qo&lsquo;pol so&lsquo;z ishlatish, o&lsquo;zini yuqori tutish va tanish-bilishchilik kabi yondashuv shakllarini mutlaqo qo&lsquo;llamaslik, ularga nisbatan doimo haqqoniy munosabatda va xolis bo&lsquo;lishlari shart.</p>\r\n\r\n<p>Pedagog xodimlar talabalarga ularni qiziqtirgan fan yoki o&lsquo;quv kursiga oid masalalar yuzasidan dars jarayonidan tashqari vaqtlarda bergan savollariga ham axloq me&rsquo;yorlariga amal qilgan holda javob qaytarishlari va ularni fanga bo&lsquo;lgan qiziqish va ishtiyoqlarini oshirish choralarini ko&lsquo;rishlari zarur.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>20-modda. Akademik ta&rsquo;qib va tazyiqqa yo&lsquo;l qo&lsquo;yilmasligi</strong></p>\r\n\r\n<p>Universitet hayotida rahbariyat yoki pedagog xodim tomonidan talabalarni ularning roziligisiz muayyan ishlarga jalb etganlik, haq to&lsquo;lamasdan ularning mehnat kuchidan foydalanish (Universitet va unga biriktirilgan boshqa hududda O&lsquo;zbekiston Respublikasi Prezidenti yoki Vazirlar Mahkamasining tegishli qarori bilan xavfsizlik standartlariga qat&rsquo;iy rioya qilingan holda ixtiyoriy shanbalik va boshqa turdagi tadbirlar tashkil etilgan hollar bundan mustasno) maqsadida ularga murojaat etilganida, talabalar tomonidan bunday so&lsquo;rovga rad javobining berilishi pedagog xodim tomonidan kelgusida ularga dars mashg&lsquo;ulotida past baho qo&lsquo;yish yoki boshqa turdagi tazyiq va ta&rsquo;qib (academic harassment) qilish bilan bog&lsquo;liq munosabat ko&lsquo;rsatilishiga imkon bermaydi va bunday ta&rsquo;qib qattiq qoralanadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>21-modda. Uyali aloqa vositalaridan foydalanish</strong></p>\r\n\r\n<p>Dars mashg&lsquo;ulotlari vaqtida uyali aloqa vositalaridan foydalanish barcha uchun qat&rsquo;iyan taqiqlanadi. Uyali aloqa vositalaridan foydalanishga zarur va uzrli holatlarda pedagog xodimning ruxsati bilangina ruxsat etilishi mumkin.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>22-modda.&nbsp;Dars mashg&lsquo;ulotida ishtirok etish</strong></p>\r\n\r\n<p>Talabalarning darsga kech qolib kelishlariga yo&lsquo;l qo&lsquo;yilmaydi. Lekin uzrli sababga ko&lsquo;ra darsga kech qolgan talaba uzr so&lsquo;rab, pedagog xodimning ijozati bilan auditoriyaga kirib o&lsquo;z joyini egallashi mumkin.</p>\r\n\r\n<p>Pedagog xodim dars mashg&lsquo;ulotlariga o&lsquo;zining nojo&lsquo;ya harakatlari bilan xalaqit berayotgan talabani yuzaga kelgan vaziyat haqida fakultet dekanini<br />\r\n(u o&lsquo;z o&lsquo;rnida bo&lsquo;lmaganda dekan o&lsquo;rinbosari yoki tyutor-guruh murabbiysini) xabardor qilgan holda darsdan chetlatishi mumkin.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>23-modda.&nbsp;Dars mashg&lsquo;ulotidan tashqari vaqtda muloqot qilish</strong></p>\r\n\r\n<p>Talaba uchun pedagog xodim bilan dars mashg&lsquo;ulotlaridan tashqari vaqtda muloqot qilish zarurati bo&lsquo;lsa, u holda muloqot:</p>\r\n\r\n<p>maslahat soatlari, mustaqil ish yoki o&lsquo;zaro kelishuv bo&lsquo;yicha belgilangan vaqtda amalga oshirilishi mumkin;</p>\r\n\r\n<p>talaba o&lsquo;zi muloqot qilmoqchi bo&lsquo;lgan pedagog xodimning lavozimi, ismi, otasining ismi va familiyasini bilishi maqsadga muvofiq.</p>\r\n\r\n<p>Asoslangan jiddiy sabablar (qo&lsquo;pollik, tamagirlik, dars sifatining pastligi, pedagog xodimning aybi bilan mashg&lsquo;ulotlar o&lsquo;tkazilishidagi muntazam uzilish hollarini isbotlovchi dalillar va b.) hamda guruh (kurs)ning yakdil fikri mavjud bo&lsquo;lgan holatlarda talabalar pedagog xodimni almashtirish haqida iltimos bilan fakultet dekaniga murojaat qilishlari mumkin.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>24-modda. Subordinatsiya</strong></p>\r\n\r\n<p>Rahbar xodimlarga xodim, talaba va doktorantlar tomonidan biron-bir masala yuzasidan vujudga kelgan holatlar bo&lsquo;yicha murojaat qilinishi muayyan tartib (subordinatsiya tamoyili), ya&rsquo;ni munosabat bildirishdagi rahbariyat bo&lsquo;g&lsquo;inlariga bosqichma-bosqich chiqish asosida tashkil etiladi. Universitet rektoriga talabalarning to&lsquo;g&lsquo;ridan-to&lsquo;g&lsquo;ri murojaat qilish holatlari bundan mustasno.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>25-modda. Tashabbus va faollik</strong></p>\r\n\r\n<p>Xodim, talaba<strong>&nbsp;</strong>va doktorantlarning Universitetda ma&rsquo;naviy-axloqiy muhitni yanada yaxshilash, ta&rsquo;lim sifatini oshirish, innovatsion g&lsquo;oyalardan samarali foydalanish, turli xil manfaatli tadbirlar uyushtirish bo&lsquo;yicha tashabbus va g&lsquo;oyalari rag&lsquo;batlantiriladi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>7-bob.&nbsp;Xodim, talaba va doktorantlarning odob-axloqqa oid majburiyatlari</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>26-modda.&nbsp;Odob-axloqqa oid majburiyatlar</strong></p>\r\n\r\n<p>Universitetga o&lsquo;qishga, ishga kirayotgan shaxslar mazkur Kodeks bilan yozma ravishda (imzo chektirib) tanishtiriladilar.</p>\r\n\r\n<p>Xodim, talaba<strong>&nbsp;</strong>va doktorantlar:</p>\r\n\r\n<p>qonun hujjatlari va mazkur Kodeks talablariga rioya etishga;</p>\r\n\r\n<p>doimo yuksaklikka intilish, halollik va adolat bilan hayot kechirish kabi olijanob fazilatlarni chuqur anglashga;</p>\r\n\r\n<p>odob-axloqqa oid milliy an&rsquo;analarimiz, urf-odat va qadriyatlarimizni hurmat qilishga;</p>\r\n\r\n<p>o&lsquo;z ustilarida doimiy ravishda ishlash va qabul qilinayotgan qonun hujjatlarini muntazam ravishda o&lsquo;rganib borishga;</p>\r\n\r\n<p>o&lsquo;z vazifalarini vijdonan, professional darajada amalga oshirishga;</p>\r\n\r\n<p>Universitet obro&lsquo;-e&rsquo;tibori va nufuziga dog&lsquo; tushiradigan har qanday harakatlarni sodir etishdan o&lsquo;zini tiyishga;</p>\r\n\r\n<p>Universitet to&lsquo;g&lsquo;risidagi axborotlardan uning manfaatlari va ishchanlik obro&lsquo;siga ziyon etkazish maqsadida foydalanmaslikka;</p>\r\n\r\n<p>Universitet mulkiga ehtiyotkorlik bilan munosabatda bo&lsquo;lish (ko&lsquo;char va ko&lsquo;chmas mulk, o&lsquo;simlik va hayvonot dunyosiga va b.), shu jumladan, xizmat vazifasini bajarish uchun berilgan moddiy texnika vositalaridan to&lsquo;g&lsquo;ri va tejamkorona foydalanishga;</p>\r\n\r\n<p>elektr energiyasi va suvni tejamkorona ishlatishga;</p>\r\n\r\n<p>biron-bir noxush voqea yoki hodisa ro&lsquo;y bersa, u haqda zudlik bilan Universitet rahbariyatiga xabar berishga;</p>\r\n\r\n<p>belgilangan cheklovlar va taqiqlarga rioya qilish, o&lsquo;z vazifalarini og&lsquo;ishmay bajarishga, xodim, talaba<strong>&nbsp;</strong>va doktorantlarning shaxsiy va oilaviy muammolarini muhokama qilmaslikka, hech bir shaxs haqida jinsi, irqi, millati, tili, diniy e&rsquo;tiqodi, ijtimoiy kelib chiqishi va lavozimi haqida hamda boshqa xususiyatlaridan qat&rsquo;i nazar noto&lsquo;g&lsquo;ri fikr yuritmaslikka va uni kamsitmaslikka;</p>\r\n\r\n<p>xodim, talaba<strong>&nbsp;</strong>va doktorantlar, shuningdek, boshqa shaxslar haqida turli ig&lsquo;vo, fitna, g&lsquo;iybat va bo&lsquo;htonlar uyushtirmaslikka va tarqatmaslikka;</p>\r\n\r\n<p>Universitet ishchanlik obro&lsquo;si yoki nufuziga putur etkazadigan nizoli vaziyatlarga yo&lsquo;l qo&lsquo;ymaslikka;</p>\r\n\r\n<p>xodim, talaba<strong>&nbsp;</strong>va doktorantning mehnat va o&lsquo;quv jarayonidagi sa&rsquo;y-harakatlariga qasddan ziyon etkazmaslikka;</p>\r\n\r\n<p><a name=\"_Hlk88779596\">xotin-qizlarning sha&rsquo;ni va qadr-qimmatini kamsitadigan harakatlar sodir etmaslikka, shilqimlik qilmaslikka, o&lsquo;zaro munosabatlarda umume&rsquo;tirof etilgan axloq qoidalarini mensimaslikda ifodalanuvchi behayo so&lsquo;zlardan foydalanmaslikka;</a></p>\r\n\r\n<p>davlat organlari va mansabdor shaxslarning, shuningdek, Universitet rahbariyatining o&lsquo;z vakolatlari doirasida qabul qilgan (bergan) qarorlarini (topshiriqlarini) o&lsquo;z vaqtida va sifatli bajarishga;</p>\r\n\r\n<p>shaxsiy foydasi hamda o&lsquo;zgalar manfaatini ko&lsquo;zlab o&lsquo;z mavqeini suiiste&rsquo;mol qilmaslikka;</p>\r\n\r\n<p>haqiqatni gapirishga, rahbarlar va boshqa xodimlarni chalg&lsquo;itmaslikka;</p>\r\n\r\n<p>mutasaddi xodimlarning ruxsatisiz turli reklama vositalarini o&lsquo;rnatmaslikka;</p>\r\n\r\n<p>kasbiy faoliyati davomida o&lsquo;zlariga ma&rsquo;lum bo&lsquo;lgan, ularning oshkor etilganligi uchun qonun hujjatlarida belgilangan tartibda javob beriladigan axborotning saqlanishi va maxfiyligini ta&rsquo;minlash yuzasidan barcha choralarni ko&lsquo;rishga;</p>\r\n\r\n<p>sog&lsquo;lom turmush tarzini yuritish va atrofdagilarning sog&lsquo;lig&lsquo;ini saqlashga g&lsquo;amxo&lsquo;rlik qilish, estetik va ekologik madaniyatning oshishiga ko&lsquo;maklashishga;</p>\r\n\r\n<p>tanqidiy mulohazalarni bildirishga va ob&rsquo;ektiv qaror qabul qilishga, o&lsquo;z xato va kamchiliklarini anglash va bartaraf etishga;</p>\r\n\r\n<p>moddiy jihatdan yaxshi ta&rsquo;minlanganligini turli yo&lsquo;llar bilan ataylab ko&lsquo;z-ko&lsquo;z qilmaslikka;</p>\r\n\r\n<p>Axborot-resurs markazi xodimlari bilan xushmuomala bo&lsquo;lishga, kitoblar va jihozlarga ehtiyotkorona munosabatda bo&lsquo;lishga, u erda uyali aloqa vositalarini o&lsquo;chirib qo&lsquo;yish yoki ovozsiz rejimga qo&lsquo;yishga, baland ovozda so&lsquo;zlashmaslik va atrofdagilarga xalaqit bermaslikka, oziq-ovqat iste&rsquo;mol qilmaslik, qog&lsquo;oz, saqich va boshqa chiqindilarni qoldirib ketmaslikka, kitoblarni olish va topshirish tartib-qoidalariga rioya qilishga;</p>\r\n\r\n<p>sport majmuasiga sport kiyimi va poyabzalida kirishga;</p>\r\n\r\n<p>sport inventarlariga nisbatan ehtiyotkorona munosabatda bo&lsquo;lishga;</p>\r\n\r\n<p>mashg&lsquo;ulotlardan keyin sport inventarlarini belgilangan joylarga qayta topshirishga;</p>\r\n\r\n<p>sport majmuasining belgilangan tartib-qoidalariga rioya qilishga;</p>\r\n\r\n<p>Universitet auditoriyalari, binolari va binolarga tutashgan hududda tozalikni saqlashga;</p>\r\n\r\n<p>hududni ifloslantirmaslik, chiqindilarni joylarda qo&lsquo;yilgan maxsus qutilarga tashlashga;</p>\r\n\r\n<p>shaxsiy avtomobilni taqiqlangan joyda qoldirmaslik, yo&lsquo;l harakati qoidalarini buzmaslik&nbsp; va mensimaslikka (beparvo bo&lsquo;lish), shuningdek, transport vositalaridan foydalanishda xavf-xatar yaratmaslikka;</p>\r\n\r\n<p>ish (o&lsquo;qish)dan tashqari vaqtda umumiy qabul qilingan odob-axloq normalariga rioya etishlari, g&lsquo;ayriijtimoiy xatti-harakatlarga yo&lsquo;l qo&lsquo;ymaslikka majbur.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>27-modda.&nbsp;Odob-axloqqa oid qo&lsquo;shimcha talablar</strong></p>\r\n\r\n<p><strong>&nbsp;a) talabalar</strong>:</p>\r\n\r\n<p>nutq madaniyatini doimiy takomillashtirib borishga;</p>\r\n\r\n<p>talabalarning o&lsquo;z-o&lsquo;zini boshqarish tizimini faol qo&lsquo;llab-quvvatlash va mustahkamlash, ijodiy faoliyatni rivojlantirish va jamoaviy madaniyatni o&lsquo;stirishga;</p>\r\n\r\n<p>pedagog xodim bilan boshqa talabalarning bahosini muhokama qilmaslikka;</p>\r\n\r\n<p>yozma ishlarni himoya qilish va reyting nazoratiga doir tartib-qoidani bajarish vaqtida chetdan yordam olmaslik, o&lsquo;zgalarga yordam ko&lsquo;rsatmaslikka;</p>\r\n\r\n<p>boshqa shaxslar tomonidan tayyorlangan topshiriqlar yoki yozma ishlarni o&lsquo;z nomidan topshirmaslikka;</p>\r\n\r\n<p>mashg&lsquo;ulotlarni sababsiz o&lsquo;tkazib yubormaslikka va darslarga sababsiz kechikib kelmaslikka;</p>\r\n\r\n<p>o&lsquo;quv mashg&lsquo;ulotlari vaqtida Universitet hududida behuda yurmaslikka;</p>\r\n\r\n<p>dars mashg&lsquo;ulotlari o&lsquo;tilayotgan vaqtda fakultet dekanlari, magistratura bo&lsquo;limi boshlig&lsquo;ining ruxsatisiz Universitet hududidan ketib qolmaslikka;</p>\r\n\r\n<p>xodim, talaba<strong>&nbsp;</strong>yoki doktorant bilan nizoli vaziyat yuzaga kelganda o&lsquo;z hissiyotlarini jilovlashga va mazkur vaziyatni ko&lsquo;rib chiqish bo&lsquo;yicha tegishli bo&lsquo;linma va xodimlarga (murabbiy (tyutor)<em>,</em>&nbsp;dekan, O&lsquo;zbekiston yoshlar ittifoqi boshlang&lsquo;ich tashkiloti, Ma&rsquo;naviyat va ma&rsquo;rifat markazi) murojaat qilishga;</p>\r\n\r\n<p>o&lsquo;quv jarayonida faol, e&rsquo;tiborli bo&lsquo;lishga va pedagog xodimning ko&lsquo;rsatmalariga qat&rsquo;iy rioya qilishga;</p>\r\n\r\n<p>dars vaqtida gaplashmaslik hamda dars mashg&lsquo;ulotiga taalluqli bo&lsquo;lmagan ishlar bilan shug&lsquo;ullanmaslikka;</p>\r\n\r\n<p>jihozlarga ehtiyotkorona munosabatda bo&lsquo;lish, stol va stullarga yozmaslikka;</p>\r\n\r\n<p>qog&lsquo;oz, saqich va boshqa keraksiz narsalarni auditoriyada qoldirib ketmaslikka;</p>\r\n\r\n<p>mashg&lsquo;ulotlar davomida ovqatlanmaslik, saqich chaynamaslikka, shuningdek, shaxsiy kompyuter&nbsp; va boshqa kommunikatsiya vositalaridan faqat pedagog xodim ruxsati bilan foydalanishga;</p>\r\n\r\n<p>pedagog xodimga mashg&lsquo;ulotlar vaqtida savol yoki iltimos bilan qo&lsquo;l ko&lsquo;targan holda va ruxsat berilganidan so&lsquo;ng murojaat qilishga;</p>\r\n\r\n<p>umumiy ovqatlanish joylarida taomlarga buyurtma berish va olishda navbat tartibiga hamda belgilangan qoidalarga rioya qilishga;</p>\r\n\r\n<p>Talabalar turar joyi Ichki tartib qoidasiga qat&rsquo;iy rioya qilishga;</p>\r\n\r\n<p>jamoat xavfsizlik manfaatlaridan kelib chiqib, imkon darajasida Universitetga jamoat transportida kelishga;</p>\r\n\r\n<p><strong>b) xodimlar:</strong></p>\r\n\r\n<p>o&lsquo;z xizmat joyidagi tartib-intizomga va Universitet ichki tartib qoidalariga rioya qilishga;</p>\r\n\r\n<p>ta&rsquo;tildan oldin yoki mehnat shartnomasi bekor qilinganda o&lsquo;z xizmat joyini talabga javob beradigan holatda qoldirishga, o&lsquo;z zimmasidagi orgtexnika vositalari va boshqa materiallarni, o&lsquo;ziga topshirilgan, lekin hali yakunlanmagan vazifalarni boshqa shaxsga topshirmaslikka;</p>\r\n\r\n<p>telefon orqali muloqot qilishda muomala madaniyati va axborot taqdim etish qoidasiga rioya qilishga (jumladan, suhbatni eng avval rasmiy tarzda salomlashishdan boshlab, so&lsquo;ng o&lsquo;z xizmat muassasasi, lavozimi hamda familiyasi, ismi, sharifini aytib, maqsadga o&lsquo;tish lozim, taqdim etilayotgan axborot maksimal qisqa, lo&lsquo;nda va aniq bo&lsquo;lishi kerak, so&lsquo;ralayotgan ma&rsquo;lumot suhbat jarayonida izlanishi tufayli telefon tarmog&lsquo;ini band qilishga yo&lsquo;l qo&lsquo;yilmaydi, zarurat bo&lsquo;lsa, qayta qo&lsquo;ng&lsquo;iroqni amalga oshirish mumkin);</p>\r\n\r\n<p>yoshlarni vatanparvarlik ruhida tarbiyalashga;</p>\r\n\r\n<p>yoshlar orasida sog&lsquo;lom turmush tarzini qaror toptirish, ularni ichkilikbozlik va giyohvandlik illatlaridan, boshqa turli halokatli tahdidlar hamda biz uchun yot bo&lsquo;lgan ekstremistik ta&rsquo;sirlardan, &ldquo;ommaviy madaniyat&rdquo; xurujlaridan ogoh etib borishga;</p>\r\n\r\n<p>ta&rsquo;lim oluvchilarni ma&rsquo;naviy-axloqiy tarbiyalashda va ma&rsquo;rifiy ishlarning samarali shakl hamda uslublarini ishlab chiqishga ko&lsquo;maklashishga;</p>\r\n\r\n<p>o&lsquo;z xizmat vazifalarini vijdonan bajarishga shubha tug&lsquo;diradigan xatti-harakatlarni qilmaslikka, talabalar bilan o&lsquo;z hamkasblarini kasbiy va shaxsiy kamchiliklarini muhokama qilmaslikka;</p>\r\n\r\n<p>talabalarni asossiz o&lsquo;quv mashg&lsquo;ulotlaridan chiqarib yubormaslikka, shuningdek, talabaga Universitet talabalar safidan chetlashtirish (kursdan kursga qoldirish) yoki talabaning majburan o&lsquo;qishdan voz kechishiga undash bilan qo&lsquo;rqitmaslikka, uning asossiz talabalar safidan chetlashtirilishiga (kursdan-kursga qoldirilishiga) olib kelmaslikka;</p>\r\n\r\n<p>akademik guruhda (kursda) talabalar xulqining umumiy madaniy holati haqida fakultet dekanlariga kerak bo&lsquo;lgan hollarda ta&rsquo;sir choralari ko&lsquo;rish lozimligi yuzasidan yozma ma&rsquo;lumot taqdim etish kabi talablarni bajaradilar.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>8-bob.&nbsp;Rag&lsquo;batlantirish va chora ko&lsquo;rish tartibi</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>28-modda.&nbsp;Xodim va talabalarni rag&lsquo;batlantirish</strong></p>\r\n\r\n<p>O&lsquo;quv yili davomida mazkur Kodeksga to&lsquo;la rioya qilgan, Universitetda yuksak ma&rsquo;naviy-axloqiy muhitning yanada qaror topishi va mustahkamlanishiga o&lsquo;z hissasini qo&lsquo;shgan xodim va talabalar rahbariyat, fakultet dekanlari, kafedra mudirlari va boshqa tarkibiy bo&lsquo;linma rahbarlari tavsiyasiga binoan belgilangan tartibda moddiy yoki ma&rsquo;naviy rag&lsquo;batlantirilishlari mumkin.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>29-modda.&nbsp;Kodeksga rioya qilishning attestatsiya va boshqa<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; jarayonlar uchun ahamiyati</strong></p>\r\n\r\n<p>Xodimlar tomonidan mazkur kodeksga rioya etilishi attestatsiyalar o&lsquo;tkazishda, yuqori va boshqa lavozimlarga tayinlash (kareraviy o&lsquo;sish) uchun kadrlar zaxirasini shakllantirishda hisobga olinadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>30-modda. Kodeks qoidalarini buzganlik uchun javobgarlik</strong></p>\r\n\r\n<p>Universitet xodimi, talabasi<strong>&nbsp;</strong>va doktoranti tomonidan mazkur Kodeks qoidalarining buzilishi uni belgilangan tartibda javobgarlikka tortishga asos bo&lsquo;lib xizmat qiladi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>31-modda.&nbsp;Kodeks va ichki tartib-qoidalarning o&lsquo;zaro munosabati</strong></p>\r\n\r\n<p>Xodim, talaba<strong>&nbsp;</strong>va doktorantlar mazkur Kodeks qoidalarini buzganida, ularga nisbatan Universitet Ichki tartib qoidalarining 7-bobida (Mehnat va o&lsquo;qish intizomini buzganlik uchun javobgarlik) qayd etilgan choralar qo&lsquo;llaniladi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>9-bob. Odob-axloq komissiyasi faoliyatini tashkil etish</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>32-modda.&nbsp;Odob-axloq komissiyasi</strong></p>\r\n\r\n<p>Mazkur Kodeks normalarining xodim, talaba<strong>&nbsp;</strong>va doktorantlar tomonidan buzilishiga oid masalalar, qoida tariqasida, Odob-axloq komissiyasi tomonidan ko&lsquo;rib chiqilishi mumkin.</p>\r\n\r\n<p>SHuningdek, Odob-axloq komissiyasi, qoida tariqasida, Universitet&nbsp;rektorining ko&lsquo;rsatmasi bo&lsquo;yicha;</p>\r\n\r\n<p>xizmat tekshiruvi natijalariga ko&lsquo;ra;</p>\r\n\r\n<p>o&lsquo;z tashabbusi bilan;</p>\r\n\r\n<p>Universitet xodimi, talabasi<strong>&nbsp;</strong>va doktorantlaridan, shuningdek, Universitetga aloqa kanallari orqali kelib tushgan axborot asosida ham ushbu turdagi masalalarni ko&lsquo;rib chiqishi mumkin.</p>\r\n\r\n<p>Odob-axloq komissiyasi kamida 5 kishidan iborat tarkibda tuziladi. Odob-axloq komissiyasining maqsadi, vazifalari, funksiyalari, huquqlari va uning faoliyatini tashkil etish bilan bog&lsquo;liq boshqa masalalar Universitet rektori tomonidan tasdiqlangan Odob-axloq komissiyasi to&lsquo;g&lsquo;risidagi nizomda belgilanadi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>33-modda. Odob-axloq komissiyasi xulosasi</strong></p>\r\n\r\n<p>Odob-axloq kodeksining buzilishi holatlarini Odob-axloq komissiyasi tomonidan ko&lsquo;rib chiqish natijalari bo&lsquo;yicha intizomiy yoki boshqa tarzdagi qoida buzilishlarining mavjudligi (mavjud emasligi) to&lsquo;g&lsquo;risida xulosa chiqariladi. Ayni vaqtda Universitet rektoriga ko&lsquo;rib chiqishi uchun qoidabuzar xodim, talaba<strong>&nbsp;</strong>va doktorantni javobgarlikka tortish to&lsquo;g&lsquo;risida taklif kiritiladi. Yo&lsquo;l qo&lsquo;yilgan qoida buzilishining xususiyatini hisobga olgan holda Odob-axloq komissiyasi xodim, talaba<strong>&nbsp;</strong>va doktorantga nisbatan Odob-axloq kodeksining buzilishiga yo&lsquo;l qo&lsquo;ymaslik to&lsquo;g&lsquo;risidagi ogohlantirish bilan cheklanishi mumkin.</p>\r\n\r\n<p>Odob-axloq kodeksiga rioya etmagan xodim, talaba<strong>&nbsp;</strong>va doktorantni intizomiy javobgarlikka tortish bo&lsquo;yicha buyruq loyihasi fakultet dekanlari va magistratura bo&lsquo;limi (talabalarga nisbatan), kadrlar bo&lsquo;limi (xodimlar va doktorantlarga nisbatan) tomonidan tayyorlanadi.</p>\r\n\r\n<p>Xodim, talaba<strong>&nbsp;</strong>va doktorantlar o&lsquo;zlari yo&lsquo;l qo&lsquo;ygan qoida buzilishi, qoida buzilishining ko&lsquo;rib chiqilishi jarayoni haqida axborotni olish va o&lsquo;zini himoya qilish uchun dalillarni taqdim etish, shuningdek, Universitet qarorlari yuzasidan belgilangan tartibda shikoyat qilish huquqiga egadirlar<em>.</em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>34-modda.&nbsp;Jamoatchilik nazorati</strong></p>\r\n\r\n<p>Xodim, talaba<strong>&nbsp;</strong>yoki doktorantning xulq-atvori ustidan jamoatchilik nazoratini ta&rsquo;minlash maqsadida, mazkur Kodeksga rioya etmaganlik holatlari tegishli jamoat tashkilotlarda ham muhokama qilinishi amaliyoti joriy etilishi mumkin.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>10-bob.&nbsp;Yakuniy qoida</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>35-modda.&nbsp;Kodeksning kuchga kirishi hamda unga o&lsquo;zgartish va<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; qo&lsquo;shimchalar kiritish</strong></p>\r\n\r\n<p>Mazkur kodeks Universitet Kengashi tomonidan tasdiqlanganidan&nbsp;so&lsquo;ng kuchga kiradi va unga o&lsquo;zgartish hamda qo&lsquo;shimchalar kiritish&nbsp;Universitet&nbsp;Kengashi qaroriga binoan amalga oshiriladi.</p>",
    "desc_ru": "<p><strong>КОДЕКС ПОВЕДЕНИЯ УРГАНЧ-РАНЧ ТЕХНОЛОГИЧЕСКОГО УНИВЕРСИТЕТА<br />\r\nДанный кодекс поведения был обсужден и одобрен на заседании Совета университета 14 января 2023 года.</strong></p>\r\n\r\n<p><strong>Глава 1. Общие правила</strong></p>\r\n\r\n<p><strong>Статья 1.</strong> Отношения, регулируемые настоящим Кодексом</p>\r\n\r\n<p>Настоящий Кодекс разработан в соответствии с Законом Республики Узбекистан &laquo;Об образовании&raquo; и другими законами и нормативными актами, регулирующими отношения, связанные с принципами, нормами профессиональной этики, образовательным процессом и основными правилами поведения докторантов (далее &ndash; работник, студент и докторант).</p>\r\n\r\n<p><strong>Статья 2</strong>. Цели и задачи кодекса поведения</p>\r\n\r\n<p>Цели Кодекса поведения:</p>\r\n\r\n<p>развитие общей культуры среди сотрудников, студентов и докторантов;</p>\r\n\r\n<p>Формирование современного имиджа сотрудников университета, студентов и докторантов;</p>\r\n\r\n<p>воспитание сотрудников, студентов и докторантов в духе уважения к Университету и его ценностям;</p>\r\n\r\n<p>Целью является совершенствование концепции университетского этикета и выработка единого подхода к требованиям внешнего вида и поведения в университете.</p>\r\n\r\n<p>Задачами кодекса поведения являются:</p>\r\n\r\n<p>профилактика правонарушений и преступлений, ненадлежащего поведения, связанного с нарушениями правил поведения среди сотрудников, студентов и докторантов, в том числе пропаганда и поощрение насилия, жестокости и непристойности, а также различных негативных пороков и защита от влияния и нападок со стороны идеи и взгляды, чуждые нашему национальному менталитету, экстремизм, сепаратизм, фундаментализм и &laquo;народная культура&raquo;;</p>\r\n\r\n<p>определить причины и условия возникновения такого ненадлежащего поведения и устранить их;</p>\r\n\r\n<p>воспитание сотрудников, студентов и докторантов в духе высокой правосознательности, строгого соблюдения Конституции, законов и других нормативных правовых документов Республики Узбекистан;</p>\r\n\r\n<p>формирование и совершенствование способности сотрудников, студентов и докторантов всегда уважать и защищать права, свободы и интересы граждан;</p>\r\n\r\n<p>формирование патриотизма, высоких духовно-нравственных качеств у сотрудников, студентов и докторантов и их воспитание в духе уважения наших национальных ценностей, уважения чести и достоинства женщин, не допущения неподобающего поведения по отношению к ним;</p>\r\n\r\n<p>Формирование и развитие здоровой социально-психологической среды в университете;</p>\r\n\r\n<p>Создание условий для формирования культуры внешнего вида у сотрудников вуза, студентов и докторантов;</p>\r\n\r\n<p>Сохранение и дальнейшее повышение авторитета и престижа университета в жизни государства и общества, а также в системе образования.</p>\r\n\r\n<p><strong>Статья 3.</strong> Область применения Кодекса</p>\r\n\r\n<p>Настоящий Кодекс распространяется на всех работников, студентов и докторантов Университета.</p>\r\n\r\n<p>Глава 2. Принципы Кодекса</p>\r\n\r\n<p><strong>Статья 4</strong>. Основные принципы поведения сотрудников вуза, студентов и докторантов</p>\r\n\r\n<p>В основе настоящего Кодекса лежат принципы законности, приоритета прав, свобод и законных интересов граждан, патриотизма, верности долгу службы и учебы, справедливости, честности и беспристрастности, оперативности и экономичности.</p>\r\n\r\n<p><strong>Статья 5.</strong> Принцип законности</p>\r\n\r\n<p>Сотрудники Университета, студенты и докторанты строго соблюдают законодательство Республики Узбекистан и выполняют свои служебные и учебные обязанности в соответствии с должностными инструкциями, трудовыми договорами, положениями настоящего Кодекса, Внутреннего распорядка Университета и других образовательных нормативных актов, действующих в Университете. соответствии с государственными документами.</p>\r\n\r\n<p><strong>Статья 6</strong>. Права, свободы и законность граждан<br />\r\n&nbsp;принцип приоритета интересов</p>\r\n\r\n<p>Права, свободы и законные интересы граждан являются высшей ценностью Университета. Сотрудники, студенты и докторанты университета не допускают нарушений прав, свобод и законных интересов граждан, а в случае таких нарушений способствуют их восстановлению.</p>\r\n\r\n<p><strong>Статья 7.</strong> Приверженность патриотизму, служению и академическому долгу<br />\r\n&nbsp;принцип</p>\r\n\r\n<p>Сотрудники, студенты и докторанты Университета осуществляют свою учебную и служебную деятельность на основе духовно-нравственных ценностей, верности Родине, верности долгу служения и учебы, выражая запрос общества и доверие к Университету. Сотрудники, студенты и докторанты выполняют свои учебные и служебные обязанности взаимно доброжелательно, независимо от их интересов и мировоззренческих взглядов.</p>\r\n\r\n<p><strong>Статья 8</strong>. Принцип справедливости, честности и беспристрастности</p>\r\n\r\n<p>Сотрудники, студенты и докторанты Университета должны быть добросовестными, честными и беспристрастными при осуществлении своей служебной и учебной деятельности и ссылаться на Университет, его сайты и социальные сети.</p>\r\n\r\n<p><br />\r\nКо всем юридическим и физическим лицам, совершившим его, следует относиться с учетом требований этого принципа.</p>\r\n\r\n<p><strong>Статья 9.</strong> Принцип эффективности и экономичности</p>\r\n\r\n<p>Сотрудники, студенты и докторанты университета постоянно повышают эффективность своей работы за счет внедрения инновационных технологий и другими способами.</p>\r\n\r\n<p>Сотрудники университета, студенты и докторанты, в свою очередь, ответственно и бережно относятся к имуществу университета, своему времени и времени других людей.</p>\r\n\r\n<p><strong>Глава 3. Борьба с коррупцией</strong></p>\r\n\r\n<p><strong>Статья 10</strong>. Принятие любой формы и проявления коррупции<br />\r\n&nbsp;не делать</p>\r\n\r\n<p>Сотрудники, студенты и докторанты университета не приемлют никаких форм и проявлений коррупции и принимают правовые меры солидарности против ее проявления каким-либо образом.</p>\r\n\r\n<p>Сотрудники, студенты и докторанты обязаны бороться с коррупцией и активно способствовать ее предотвращению, а также безоговорочно выполнять требования Закона Республики Узбекистан &laquo;О борьбе с коррупцией&raquo; от 01.03.2017 № 419, они должны выполнять свои деятельность открыто и справедливо, строго придерживаться законности, сохраняя при этом верность высоким моральным ценностям и принципам.</p>\r\n\r\n<p><strong>Глава 4. Требования к поведению и официальному общению сотрудников, студентов и докторантов</strong></p>\r\n\r\n<p><strong>Статья 11</strong>. Правила университетской одежды и внешнего вида</p>\r\n\r\n<p>Сотрудники университета, студенты и докторанты должны носить современную, ненавязчивую одежду, соответствующую их учебе и профессии. Они также должны принести с собой необходимые учебные материалы.</p>\r\n\r\n<p>Не допускается добавление в форму студентов, допущенных к поступлению в Университет, элементов (хиджаб, кипа, кашая, крест и т.п.), отражающих принадлежность к разным религиям, конфессиям и субкультурам.</p>\r\n\r\n<p>Сотрудникам, студентам и докторантам запрещается ношение верхней одежды (накидок, пальто, курток и т.п.) в аудитории и служебных помещениях.</p>\r\n\r\n<p>Внешний вид и одежда сотрудников, студентов и докторантов должны быть опрятными и чистыми.</p>\r\n\r\n<p><strong>Статья 12</strong>. Участие в собраниях и собраниях</p>\r\n\r\n<p>Во время участия в различных мероприятиях (собраниях, торжественных собраниях, собраниях, торжествах) сотрудники университета, студенты и докторанты обязаны относиться к выступающим с уважением, сохранять мир и спокойствие во время мероприятия, без разрешения председателя и модератора. невозможно бросить перекусить и поговорить. При необходимости возможен вход и выход из зала заседаний между выступлениями.</p>\r\n\r\n<p><strong>Статья 13. </strong>Соблюдайте правила поведения в зданиях</p>\r\n\r\n<p>При входах и выходах из зданий, а также в коридорах студенты должны проходить мимо сотрудников, мужчин и женщин, а молодые люди должны проходить перед ними взрослых.</p>\r\n\r\n<p>Каждый входящий в здание должен открыто предъявить документ, удостоверяющий личность (служебный или студенческий билет, паспорт и т.п.), лицу, ответственному за контроль входа и выхода в здание, или пройти через турникеты по специально выданному удостоверению личности. должен.</p>\r\n\r\n<p>Сотрудники, студенты и докторанты должны ходить по правой стороне дороги на территории Университета, не должны громко разговаривать по мобильным устройствам в коридорах и холлах. При встрече рекомендуется здороваться друг с другом: ученики первыми приветствуют сотрудников, молодые люди первыми приветствуют взрослых.</p>\r\n\r\n<p><strong>Статья 14.</strong> Официальное общение сотрудников, студентов и докторантов<br />\r\n&nbsp;стандарты</p>\r\n\r\n<p>При взаимодействии с организациями и учреждениями, средствами массовой информации и гражданами сотрудники университета, студенты и докторанты обязаны соблюдать следующие нормы и правила официального общения:</p>\r\n\r\n<p>осуществлять свои действия в интересах Университета, поддерживать и улучшать его имидж, не совершать действий, наносящих вред имени и интересам сотрудников Университета, студентов и докторантов, а также демонстрировать примерное поведение при общении с ими и в переписке в социальных сетях создают весьма положительное впечатление об Университете своим характером;</p>\r\n\r\n<p>отношения с женщинами должны основываться на требованиях действующего законодательства, национальных традициях и принципах взаимного уважения;</p>\r\n\r\n<p>Не распространять информацию об Университете, его сотрудниках, студентах и ​​докторантах, не соответствующую действительности или искаженную, допускающую ложное толкование, допускать распространение такой информации не в пищу, а также не произносить выступлений на эту тему публично. и в социальных сетях;</p>\r\n\r\n<p>не разглашать информацию о личной жизни сотрудников, студентов и докторантов без их согласия;</p>\r\n\r\n<p>не уточнять информацию о сотрудниках, студентах и ​​докторантах, не связанную с их профессиональной и образовательной деятельностью;</p>\r\n\r\n<p>служебная информация</p>",
    "desc_en": "<p>URGANCH RANCH UNIVERSITY OF TECHNOLOGY CODE OF CONDUCT<br />\r\nThis code of conduct was discussed and approved at the meeting of the University Council on January 14, 2023.</p>\r\n\r\n<p>Chapter 1. General rules</p>\r\n\r\n<p>Article 1. Relations regulated by this code</p>\r\n\r\n<p>This Code was developed in accordance with the Law of the Republic of Uzbekistan &quot;On Education&quot; and other relevant laws and regulations. It governs relationships concerning the principles and norms of professional ethics, the educational process, and the fundamental rules of conduct for employees, students, and doctoral students.</p>\r\n\r\n<p>Article 2. Goals and objectives of the code of conduct</p>\r\n\r\n<p>Objectives of the Code of Conduct:</p>\r\n\r\n<p>developing a shared culture among employees, students, and doctoral students;</p>\r\n\r\n<p>shaping a modern image of university employees, students, and doctoral students;</p>\r\n\r\n<p>instilling respect for the University and its values among employees, students, and doctoral students;</p>\r\n\r\n<p>enhancing the concept of university etiquette and establishing a unified approach to standards of appearance and behavior within the University.</p>\r\n\r\n<p>The tasks of the code of conduct are as follows:</p>\r\n\r\n<p>prevention of delinquency and crime, inappropriate behavior related to violations of the rules of conduct among employees, students and doctoral students, including the promotion and encouragement of violence, cruelty and obscenity, as well as various negative vices and protection from the influence and attacks of ideas and views foreign to our national mentality, extremism, separatism, fundamentalism and &quot;popular culture&quot;;</p>\r\n\r\n<p>to determine the reasons and conditions for the occurrence of such inappropriate behavior and to eliminate them;</p>\r\n\r\n<p>educating employees, students, and doctoral students in the spirit of high legal awareness and strict adherence to the Constitution, laws, and other regulatory legal documents of the Republic of Uzbekistan;</p>\r\n\r\n<p>developing and enhancing the ability of employees, students, and doctoral students to consistently respect and protect the rights, freedoms, and interests of citizens;</p>\r\n\r\n<p>fostering patriotism and high spiritual and moral qualities in employees, students, and doctoral students, and nurturing them with respect for national values, promoting respect for the honor and dignity of women and preventing any inappropriate behavior toward them;</p>\r\n\r\n<p>Establishing and maintaining a healthy social and psychological environment at the university;</p>\r\n\r\n<p>Creating conditions for cultivating a culture of appearance among university employees, students, and doctoral students;</p>\r\n\r\n<p>Preserving and enhancing the authority and prestige of the university in the state, society, and the educational system.</p>\r\n\r\n<p>Article 3. Scope of the Code</p>\r\n\r\n<p>This Code applies to all employees, students and doctoral students of the University.</p>\r\n\r\n<p>Chapter 2. Principles of the Code</p>\r\n\r\n<p>Article 4. Basic principles of the behavior of university employees, students and doctoral students</p>\r\n\r\n<p>This Code is founded on the principles of legality, prioritizing the rights, freedoms, and legal interests of citizens, as well as patriotism, loyalty to the duties of service and study, justice, honesty, impartiality, efficiency, and frugality.</p>\r\n\r\n<p>Article 5. The principle of legality</p>\r\n\r\n<p>University employees, students, and doctoral students strictly adhere to the legislation of the Republic of Uzbekistan and fulfill their professional and academic responsibilities in accordance with job descriptions, employment contracts, this Code, the University&#39;s Internal Regulations, and other educational policies and official documents.</p>\r\n\r\n<p>Article 6. Citizens&#39; rights, freedoms and legal<br />\r\n&nbsp;the principle of priority of interests</p>\r\n\r\n<p>The rights, freedoms, and legal interests of citizens are the highest priority of the University. University employees, students, and doctoral students do not tolerate violations of these rights, freedoms, and legal interests. In the event of such violations, they actively contribute to their restoration.</p>\r\n\r\n<p>Article 7. Commitment to patriotism, service, and academic duty<br />\r\n&nbsp;principle</p>\r\n\r\n<p>University employees, students, and doctoral students conduct their academic and professional activities based on spiritual and moral values, loyalty to the Motherland, and dedication to their duties, reflecting society&#39;s expectations and trust in the University. They fulfill their academic and professional responsibilities with mutual respect and goodwill, regardless of personal interests or ideological views.</p>\r\n\r\n<p>Article 8. The principle of justice, honesty and impartiality</p>\r\n\r\n<p>University employees, students, and doctoral students should be fair, honest, and impartial in carrying out their academic and professional activities, and when referring to the University, its websites, and social media platforms.</p>\r\n\r\n<p>All legal entities and individuals involved must be treated in accordance with the principles outlined above.</p>\r\n\r\n<p>Article 9. The principle of efficiency and economy</p>\r\n\r\n<p>University employees, students, and doctoral students continuously enhance the efficiency of their work by implementing innovative technologies and through other means.</p>\r\n\r\n<p>University employees, students and doctoral students, in turn, also treat the University&rsquo;s property, their own time, and the time of others with responsibility and care.</p>\r\n\r\n<p>Chapter 3. Fight against corruption</p>\r\n\r\n<p>Article 10. Accepting any form and appearance of corruption<br />\r\n&nbsp;not to do</p>\r\n\r\n<p>University employees, students, and doctoral students reject all forms and manifestations of corruption and take legal action in solidarity to combat it in any form.</p>\r\n\r\n<p>Employees, students, and doctoral students must actively fight against corruption and contribute to its prevention. They are also required to unconditionally comply with the Law of the Republic of Uzbekistan &quot;On Combating Corruption,&quot; dated January 3, 2017, No. 419. They must conduct their activities openly and fairly, adhere strictly to the rule of law, and remain loyal to high moral values and principles.</p>\r\n\r\n<p>Chapter 4. Requirements for behavior and official communication of employees, students and doctoral students</p>\r\n\r\n<p>Article 11. University dress and appearance rules</p>\r\n\r\n<p>University employees, students, and doctoral students should wear modern, modest clothing appropriate for their studies and profession. They must also bring the necessary educational materials with them.</p>\r\n\r\n<p>It is not allowed to add elements (hijab, kipa, kashaya, cross, etc.) to the uniform of students, which are allowed to come to the University, which reflect belonging to different religions, denominations and subcultures.</p>\r\n\r\n<p>Employees, students and doctoral students are prohibited from wearing outerwear (cloaks, coats, jackets, etc.) in the auditorium and service rooms.</p>\r\n\r\n<p>The appearance and clothes of employees, students and doctoral students should be neat and clean.</p>\r\n\r\n<p>Article 12. Participation in meetings and gatherings</p>\r\n\r\n<p>During their participation in various events (meetings, solemn gatherings, meetings, celebrations), university employees, students and doctoral students are obliged to treat speakers with respect, maintain peace and tranquility during the event, without the permission of the chairman and moderator. it is impossible to throw a bite and speak. If necessary, it is possible to enter and leave the meeting hall between speeches.</p>\r\n\r\n<p>Article 13. Follow the rules of behavior in buildings</p>\r\n\r\n<p>At the entrances and exits of the buildings, as well as on the corridors, students must pass the staff, men and women, and young people must pass the adults before them.</p>\r\n\r\n<p>Each person entering the building must openly show their identity document (service or student ID card, passport, etc.) to the person responsible for controlling entry and exit to the building or pass through the turnstiles with a specially issued ID card. teeth are a must.</p>\r\n\r\n<p>Employees, students and doctoral students should walk on the right side of the road on the University territory, and should not talk loudly on mobile devices in corridors and halls. When meeting each other, it is recommended to greet each other: students greet staff first, young people greet adults first.</p>\r\n\r\n<p>Article 14. Official communication of employees, students and doctoral students<br />\r\n&nbsp;standards</p>\r\n\r\n<p>When interacting with organizations and institutions, mass media, and citizens, university employees, students, and doctoral students must adhere to the following norms and rules of official communication:</p>\r\n\r\n<p>to carry out their actions in the interest of the University, to maintain and improve its image, not to carry out actions that harm the name and interests of the University&#39;s employees, students and doctoral students, as well as to demonstrate exemplary behavior when communicating with them and in correspondence on social networks create a highly positive impression of the University with its character;</p>\r\n\r\n<p>relationships with women must be based on the requirements of current legislation, national traditions, and principles of mutual respect.;</p>\r\n\r\n<p>They should refrain from spreading false or misrepresented information about the University, its employees, students, or doctoral students that could lead to misinterpretation. Such information should not be disseminated, nor should speeches on this topic be made in public or on social media platforms.</p>\r\n\r\n<p>Personal information about employees, students, and doctoral students should not be disclosed without their consent;</p>\r\n\r\n<p>Information about employees, students, and doctoral students that is not related to their professional or educational activities should not be discussed.</p>\r\n\r\n<p>Confidential or service-related information should not be shared inappropriately.</p>"
  }
];

